                'body_help' => '<strong>હંમેશાં ઉપલબ્ધ:</strong> [ticket_reference], [ticket_url], [ticket_subject], [ticket_status], [ticket_priority], [requester_name], [requester_first_name], [requester_email], [analyst_name], [analyst_email], [department_name], [created_date], [closed_date].<br><br><strong>વિશ્લેષકને મોકલાતા ઈમેઈલ માટે:</strong><br>[assigned_analyst_name], [assigned_analyst_first_name], [assigned_analyst_email] &mdash; ટિકિટ જે વિશ્લેષકને <em>સોંપાયેલી</em> છે તે.<br>[ticket_url_analyst] &mdash; ઇનબોક્સમાં ટિકિટ ખોલતી લિંક. [ticket_url] ને બદલે આ વાપરો, કારણ કે તે ગ્રાહકનું પોતાનું વ્યૂ ખોલે છે અને તેને પોર્ટલ એકાઉન્ટ જોઈએ છે.<br><br>&#9888; <strong>[analyst_name] હંમેશાં સોંપાયેલ વિશ્લેષક હોતો નથી.</strong> ટિકિટનો <em>માલિક</em> સેટ કરેલો હોય ત્યાં તે માલિકનું નામ આપે છે, અને ન હોય ત્યારે સોંપાયેલ વિશ્લેષક પર પાછું આવે છે &mdash; મોટા ભાગની સર્વિસ ડેસ્ક પર આ બે અલગ વ્યક્તિઓ હોય છે. ગ્રાહકને કોણ તેમનું ધ્યાન રાખે છે તે જણાવવા માટે આ જ સાચો કોડ છે. પણ જ્યારે ઈમેઈલ હમણાં જ સોંપાયેલા કામ વિશે <em>વિશ્લેષકને જ</em> મોકલવાનો હોય, ત્યારે [assigned_analyst_name] વાપરો.<br><br><strong>ફક્ત અમુક ટ્રિગર પર:</strong><br>[note_text] &mdash; <strong>વિનંતીકર્તા સાથે નોંધ શેર કરી</strong> પર, નોંધ પોતે. તેને છોડી દો તો ઈમેઈલ ફક્ત એટલું કહે છે કે અપડેટ છે.<br>[ticket_closed_message] &mdash; <strong>ટિકિટ બંધ થઈ</strong> પર, ટિકિટ બંધ કરતી વખતે વિશ્લેષક લખે તે એક વખતની નોંધ. તેને ઉમેરો તો તેમને એ નોંધ માટે પૂછવામાં આવે છે; ન ઉમેરો તો પૂછવામાં આવતું નથી.<br><br>HTML સપોર્ટેડ છે (દા.ત. સ્ટાઇલ કરેલા બટન).',
