            'cron_help' => 'શેડ્યૂલ થયેલું ટાસ્ક બેકગ્રાઉન્ડમાં રાહ જોતા ડોક્યુમેન્ટ પર કામ કરે છે. વ્યસ્ત સર્વિસ ડેસ્ક માટે આ યોગ્ય જવાબ છે, અને તમારા સર્વર પર શેડ્યૂલ થયેલું ટાસ્ક સેટ કરવું જરૂરી છે. તેના વગર, કંઈ ગુમાવાતું નથી &mdash; ડોક્યુમેન્ટ તેના બદલે નીચેના વિકલ્પ દ્વારા વંચાય છે, ફક્ત ધીમેથી.',
