            'empty_block_title' => 'બંધ કરવાનો ઇનકાર કરો',
            'empty_block_desc' => 'ઓછામાં ઓછી એક ચેકલિસ્ટ જોડાય નહીં ત્યાં સુધી ટિકિટ બંધ સ્થિતિ સુધી પહોંચી શકશે નહીં.',
            'always_recorded' => 'કોઈપણ રીતે, પગલાં બાકી હોય ત્યારે બંધ કરવાથી એક આંતરિક નોંધ લખાય છે જે છોડાયેલા પગલાં, કોણે તેને બંધ કરી અને કયા ઇન્ટરફેસ દ્વારા તે જણાવે છે. આ સેટિંગ્સ નક્કી કરે છે કે તેની મંજૂરી છે કે નહીં, ક્યારેય નહીં કે તે લોગ થાય છે કે નહીં.',
