        'mandatory' => [
            'when_heading' => 'જ્યારે ટિક કરેલું ફીલ્ડ ખાલી હોવા છતાં ટિકિટ બંધ થાય',
            'warn_title' => 'ચેતવણી આપો',
            'warn_desc' => 'વિશ્લેષકને કહેવામાં આવે છે કે કયા ફીલ્ડ્સ ખાલી છે અને તે છતાં પણ બંધ કરી શકે છે.',
            'notify_title' => 'ચેતવણી આપો, અને કોઈને ઈમેઇલ કરો',
            'notify_desc' => 'એ જ, અને નીચેના લોકોને ટિકિટ, ખાલી ફીલ્ડ્સ અને કોણે તેને બંધ કરી તેનું નામ આપતો ઈમેઇલ મળે છે - ઉદાહરણ તરીકે, સર્વિસ ડિલિવરી મેનેજર.',
            'notify_label' => 'ઈમેઇલ આને મોકલો',
