            'block_title' => 'બંધ કરવાનો ઇનકાર કરો',
            'block_desc' => 'દરેક ટિક કરેલું ફીલ્ડ ભરાય નહીં ત્યાં સુધી ટિકિટ બંધ સ્થિતિ સુધી પહોંચી શકતી નથી.',
            'record_title' => 'તેને ટિકિટ પર નોંધો',
            'record_desc' => 'ખાલી ફીલ્ડ્સ, કોણે ટિકિટ બંધ કરી અને કેવી રીતે તેનું નામ આપતી ઇન્ટરનલ નોંધ લખે છે. ફક્ત બે ચેતવણી વિકલ્પોને લાગુ પડે છે - ઇનકાર કરેલ બંધ કંઈ બદલતું નથી, તેથી નોંધવા માટે કંઈ નથી.',
            'record_blocked' => 'જ્યારે બંધ કરવાનો ઇનકાર થાય ત્યારે કંઈ નોંધાતું નથી, કારણ કે ટિકિટ બંધ થતી નથી.',
            'fields_heading' => 'બંધ કરતા પહેલા ભરવું આવશ્યક',
            'fields_hint' => 'ટિકિટની કંપની માટે બંધ કરેલું ફીલ્ડ, અથવા ટીમો વગરના ઇન્સ્ટોલ પર ટીમ ફીલ્ડ, તે ટિકિટ માટે છોડી દેવાય છે - કોઈને એવી વસ્તુ ભરવાનું કહેવામાં આવતું નથી જે તેઓ જોઈ શકતા નથી. ટિકિટો મર્જ કરવાથી આ ક્યારેય ટ્રિગર થતું નથી.',
            'choose_mode' => 'ફીલ્ડ્સ ખાલી હોય ત્યારે શું થાય તે પસંદ કરો.',
            'need_address' => 'ઈમેઇલ કરવા માટે ઓછામાં ઓછું એક સરનામું ઉમેરો.',
