        'intros' => [
            'checklists' => 'ચેકલિસ્ટ પગલાંને ફરજિયાત તરીકે માર્ક કરી શકે છે. આ નક્કી કરે છે કે તે પગલાં ટિક થાય તે પહેલાં કોઈ ટિકિટ બંધ કરે તો શું થાય છે.',
            'mandatory_fields' => 'ટિકિટ બંધ થાય તે પહેલાં કયા ટિકિટ ફીલ્ડ્સ ભરવા આવશ્યક છે તે પસંદ કરો, અને જ્યારે કોઈ તેમાંથી કોઈપણ ખાલી હોય ત્યારે એક બંધ કરે તો શું થાય છે. આ નિયમ ટિકિટ બંધ કરી શકાય તેવી દરેક જગ્યાએ લાગુ પડે છે: ટિકિટ સ્ક્રીન, બલ્ક ક્રિયાઓ, REST API અને વર્કફ્લો.',
            'departments' => 'વિભાગો ટિકિટને જૂથબદ્ધ કરે છે અને તમારા સંગઠનના યોગ્ય ક્ષેત્રમાં રૂટ કરે છે — તમારો સર્વિસ ડેસ્ક કામનું વર્ગીકરણ અને સોંપણી કરવા જે વાપરે છે તે બનાવો.',
            'teams' => 'ટીમો નક્કી કરે છે કે વિશ્લેષકો કયા વિભાગ એક્સેસ કરી શકે છે. ટીમોને વિભાગો સોંપો, પછી તેમનો એક્સેસ નિયંત્રિત કરવા વિશ્લેષકોને ટીમો સોંપો.',
            'ticket_types' => 'ટિકિટ પ્રકાર વર્ગીકૃત કરે છે કે વિનંતી શું છે (દા.ત. Incident, Service Request) — વિશ્લેષકો ટિકિટ પર સેટ કરી શકે તેવા પ્રકાર વ્યાખ્યાયિત કરો.',
            'ticket_origins' => 'ટિકિટ સ્રોત નોંધે છે કે ટિકિટ કેવી રીતે આવી (દા.ત. Email, Phone, Portal) — વિશ્લેષકો પસંદ કરી શકે તેવા સ્રોત વ્યાખ્યાયિત કરો.',
            'mailboxes' => 'મેઈલબોક્સ FreeITSM ને ઈમેઈલ એકાઉન્ટ સાથે જોડે છે જેથી આવતા મેસેજ ટિકિટ બને છે અને જવાબ પાછા જાય છે — તમારો સર્વિસ ડેસ્ક જેની પર નજર રાખે છે તે ઉમેરો અને ઓથેન્ટિકેટ કરો.',
            'privacy' => 'ટિકિટમાં ફક્ત તેને ઉઠાવનાર વ્યક્તિ સાથેની તમારી વાતચીત જ હોતી નથી. સપ્લાયરને ફોરવર્ડ કરવું, અથવા સહકર્મીને CC કરવું, તે મેસેજને એ જ ટિકિટ પર મૂકે છે — અને તેમનો જવાબ પણ ત્યાં જ આવે છે. આ નક્કી કરે છે કે વિનંતીકર્તા સેલ્ફ-સર્વિસ પોર્ટલમાં તેમાંથી કેટલું જુએ છે.',
            'indexing' => 'જોડાણોની અંદરનો ટેક્સ્ટ વંચાય છે જેથી તે શોધી શકાય. Word, Excel, PowerPoint અને પ્લેન ટેક્સ્ટ ફાઈલ FreeITSM પોતે, તે આવે તે જ ક્ષણે વાંચે છે. PDF, જૂની Office ફાઈલ અને સ્કેન કરેલા ડોક્યુમેન્ટને અલગ ડોક્યુમેન્ટ-વાંચન સેવાની જરૂર છે — તે <strong>System &rarr; Integrations &rarr; Apache Tika</strong> હેઠળ સેટ કરો — અને કારણ કે તેમાં ઘણો વધુ સમય લાગે છે, તે બેકગ્રાઉન્ડમાં વંચાય છે. આ બે સ્વિચ નક્કી કરે છે કે તે બેકગ્રાઉન્ડ કામ ક્યારે થાય છે.',
            'merge_behaviour' => 'જ્યારે બે ટિકિટ એક જ વસ્તુ નીકળે, ત્યારે વિશ્લેષક તેમને મર્જ કરી શકે છે. આ સેટિંગ્સ નક્કી કરે છે કે તમારા વિનંતીકર્તાઓ પાસે જે ટિકિટ reference છે તેનું શું થાય છે, અને વાતચીતનું શું થાય છે. તે બધાને લાગુ પડે છે — મર્જ ગ્રાહક શું જુએ છે તે બદલે છે, એટલે એક જ મેઈલબોક્સ પરના બે વિશ્લેષકો તેના પર અસંમત ન થઈ શકે.',
            'reply_templates' => 'કેન્ડ (canned) જવાબો જે તમારા વિશ્લેષકો ફરીથી ટાઈપ કરવાને બદલે જવાબમાં મૂકી શકે છે. આ શેર કરેલા છે જે આખી ટીમ જુએ છે — વિશ્લેષકના પોતાના ખાનગી ટેમ્પલેટ જવાબ વિન્ડોમાંથી સાચવાય છે અને અહીં યાદીબદ્ધ નથી.',
            'rota_shifts' => 'શિફ્ટ એ કામકાજ-પેટર્ન ટેમ્પલેટ (દા.ત. Early, Late, On-call) છે જે વિશ્લેષકોને સ્ટાફ રોટા પર સોંપાય છે — રોટા બનાવતા પહેલા તેમને અહીં વ્યાખ્યાયિત કરો.',
            'analysts' => 'વિશ્લેષકો એ સ્ટાફ છે જે લોગ ઇન કરે છે અને ટિકિટ પર કામ કરે છે — તેમને ઉમેરો, પાસવર્ડ રીસેટ કરો, અને તેમનો એક્સેસ નિયંત્રિત કરવા ટીમોમાં સોંપો.',
            'general' => 'સામાન્ય સેટિંગ્સ સર્વિસ ડેસ્કનું નામ અને ડિફોલ્ટ જેવા સિસ્ટમ-વ્યાપી વિકલ્પોને નિયંત્રિત કરે છે — તમારા સંગઠનને અનુરૂપ તેમને એડજસ્ટ કરો.',
            'statuses' => 'ટિકિટ જે વર્કફ્લો સ્થિતિમાં હોઈ શકે છે તે. <em>Closed</em> તરીકે ફ્લેગ કરેલી સ્થિતિઓ ટર્મિનલ ગણાય છે — રિપોર્ટ, watchtower કાઉન્ટર અને એસાઈન પર closed-datetime ઓટો-સેટ દ્વારા વપરાય છે. બરાબર એક સ્થિતિ નવી ટિકિટ માટે ડિફોલ્ટ છે.',
            'priorities' => 'ટિકિટ પર બતાવેલા પ્રાથમિકતા બેન્ડ. બરાબર એક પ્રાથમિકતા નવી ટિકિટ માટે ડિફોલ્ટ છે.',
            'rota_locations' => 'દરેક વિશ્લેષક કોઈ ચોક્કસ દિવસે ક્યાં કામ કરી રહ્યો છે — સ્ટાફ રોટા દ્વારા વપરાય છે અને દરેક એન્ટ્રી પર રંગીન બેજ તરીકે બતાવાય છે. બરાબર એક સ્થાન નવી રોટા એન્ટ્રી માટે ડિફોલ્ટ છે.',
            'email_templates' => 'ટિકિટ ઈવેન્ટ દ્વારા ટ્રિગર થતા ઓટોમેટેડ ઈમેઈલ જવાબ. દરેક ઈવેન્ટ માટે ફક્ત પહેલું સક્રિય ટેમ્પલેટ વપરાય છે.',
        ],
        'messaging' => [
            'channels_heading' => 'મેસેજિંગ ચેનલ',
            'channels_intro' => 'ગ્રાહકોને WhatsApp પર વિશ્લેષક સાથે ચેટ કરવા દો — દરેક મેસેજ ટિકિટ બને છે, ઈમેઈલની જેમ જ. નીચે ચેનલ ઉમેરો, પછી ઈનબાઉન્ડ મેસેજ આ ઇન્સ્ટોલ સુધી પહોંચે તે માટે તેનું <strong>webhook URL</strong> તમારા પ્રોવાઇડર (Twilio અથવા Meta)માં પેસ્ટ કરો.',
            'base_url_label' => '<strong>પબ્લિક બેઝ URL</strong>',
