            'col_actions' => 'ક્રિયાઓ',
            'notifs_heading' => 'Breach નોટિફિકેશન',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">નોટિફિકેશન નિયમો કેવી રીતે કામ કરે છે</strong>દરેક નિયમના ચાર ભાગ છે: એક <strong>સ્કોપ</strong>, એક <strong>ટ્રિગર</strong>, એક <strong>ટાર્ગેટ</strong>, અને <strong>પ્રાપ્તકર્તાઓ</strong>ની યાદી.<br><br><strong>સ્કોપ</strong> ક્યાં તો <em>Default</em> (નિયમ દરેક વિભાગની ટિકિટને લાગુ પડે છે) અથવા <em>ચોક્કસ વિભાગ</em> (નિયમ ફક્ત તે વિભાગની ટિકિટને જ લાગુ પડે છે) હોઈ શકે છે.<br>જ્યારે ટિકિટનું મૂલ્યાંકન થાય છે, ત્યારે સિસ્ટમ પહેલા તેના વિભાગ સાથે મેચ થતો નિયમ શોધે છે &mdash; જો એક હોય, તો તે નિયમ જીતે છે અને ડિફોલ્ટ અવગણાય છે. જો કોઈ વિભાગ-ચોક્કસ નિયમ ન હોય, તો ડિફોલ્ટ નિયમ વપરાય છે. આ રીતે તમે દરેક વિભાગને આવરી લેતા વ્યાજબી ડિફોલ્ટ સેટ કરી શકો છો, પછી જ્યાં એક ટીમને અલગ એસ્કેલેશન જરૂરિયાત હોય ત્યાં અપવાદ કોતરી શકો છો.<br><br><strong>ટ્રિગર</strong> ક્યાં તો <em>Warning</em> (ટિકિટે warning થ્રેશોલ્ડ ઓળંગ્યો છે &mdash; સંભવિત breach નજીક આવી રહ્યો છે) અથવા <em>Breach</em> (ટિકિટે હવે તેનું SLA ટાર્ગેટ ઓળંગ્યું છે &mdash; વાસ્તવિક breach) છે. દરેક પોતાનો નિયમ છે, એટલે તમે warning વિરુદ્ધ breach માટે અલગ લોકોને સૂચિત કરી શકો છો.<br><br><strong>ટાર્ગેટ</strong> એ છે કે કયું SLA ઘડિયાળ જોવું &mdash; <em>Response</em>, <em>Resolution</em>, અથવા <em>Both</em>.<br><br><strong>પ્રાપ્તકર્તાઓ</strong> આનું કોઈપણ સંયોજન હોઈ શકે છે: ટિકિટના હાલના સોંપાયેલ વ્યક્તિ, ટિકિટના વિભાગની ટીમોના દરેક વિશ્લેષક, એક નામ આપેલ વિશ્લેષક, અને/અથવા ફ્રી-ફોર્મ ઈમેઈલ સરનામાંની યાદી (શેર્ડ ઇનબોક્સ અથવા Slack/Teams ઈમેઈલ બ્રિજ માટે ઉપયોગી).<br><br><strong style="color:var(--warning-text, #92400e);">કોઈ નિયમ = કોઈ ઈમેઈલ નહીં.</strong> ટિકિટ breach થાય તો પણ, જ્યાં સુધી તમે ઓછામાં ઓછો એક નિયમ ન ઉમેરો ત્યાં સુધી કંઈ ફાયર થતું નથી (બધા માટે કવરેજ મેળવવા Default-scope Warning + Breach જોડી સાથે શરૂ કરો).',
            'notifs_dedup' => 'દરેક ટિકિટ દરેક ટ્રિગર માટે દરેક ટાર્ગેટ દીઠ વધુમાં વધુ એક ઈમેઈલ ફાયર કરે છે &mdash; cron worker ટ્રેક રાખે છે કે શું પહેલેથી મોકલાયું છે જેથી તમને ડુપ્લિકેટ ન મળે.',
            'col_scope' => 'સ્કોપ',
