            'cron_heading' => 'Cron પ્રવૃત્તિ',
            'cron_refresh' => 'રિફ્રેશ',
            'cron_intro' => 'breach-check cron (CLI અને HTTP) ના છેલ્લા <span id="slaCronRunsLimit">20</span> invocations. Rejected requests (rate-limited, auth-failed) સામેલ છે જેથી એ જ source-of-truth rate-limit ચેક અને સિક્યુરિટી ઓડિટને સપોર્ટ કરે. <strong><span id="slaCronRetentionDays">30</span> દિવસ</strong> પછી આપોઆપ prune થાય છે; સફળ રનો વચ્ચેનો ન્યૂનતમ ઈન્ટરવલ <strong><span id="slaCronMinInterval">30</span>s</strong> છે (બંને <code>system_settings</code> માં કન્ફિગરેબલ છે).',
