            'style_random_help' => 'ત્રણ અક્ષર અને આઠ અંક, જેમ કે CKQ-418-73926. FreeITSM હંમેશા આ જ કરતું આવ્યું છે. કોઈ અંદાજ લગાવી શકતું નથી કે તમારી પાસે કેટલી ટિકિટ છે, પણ કોઈ તેને બોલી પણ શકતું નથી.',
