            'scope_per_company' => 'દરેક કંપની',
            'scope_help' => 'ટિકિટ પ્રકાર દીઠ ગણતરી કરવાથી incidents અને requests ને પોતાના નંબરના ક્રમ મળે છે, જે મોટાભાગના મોટા સર્વિસ ડેસ્ક કરે છે તે રીત છે. જો તમે અલગથી ગણો, તો ફોર્મેટે કહેવું જ પડશે કે કયું કયું છે — તેમાં {TYPE} અથવા {COMPANY} મૂકો, નહીંતર દરેક જૂથ સરખા નંબર બનાવશે.',
