            'reset_never' => 'ક્યારેય નહીં — ગણતરી ચાલુ રાખો',
            'reset_yearly' => 'દર વર્ષે',
            'reset_monthly' => 'દર મહિને',
            'reset_help' => 'ફક્ત ઉપયોગી છે જો વર્ષ અથવા મહિનો નંબરનો ભાગ હોય, નહીંતર તમને ડુપ્લિકેટ મળશે. <code>INC-{YYYY}-{#####}</code> જેવા કંઈક સાથે જોડો.',
            'existing_note' => '<strong>પહેલેથી નંબર થયેલું કંઈ બદલાતું નથી.</strong> હાલની ટિકિટ પોતાનો reference જાળવી રાખે છે, અને FreeITSM એ ક્યારેય ઈશ્યુ કરેલો દરેક reference કામ કરવાનું ચાલુ રાખે છે &mdash; જૂના ઈમેઈલના જવાબોમાં પણ. જો તમે હાલની ટિકિટને પણ ફરી નંબર આપવા માંગો છો, તો નીચે તેના માટે એક ટૂલ છે. <strong>તમારે અંક ખૂટશે નહીં:</strong> તમે પસંદ કરેલી પહોળાઈ ન્યૂનતમ છે, એટલે ટિકિટ 1,000,001 ને ફક્ત એક અંક વધુ મળે છે, તૂટતી નથી.',
            'saved' => 'ટિકિટ નંબરિંગ સાચવ્યું.',
