            'renumber_intro' => 'ઉપરની સ્કીમમાં દરેક હાલની ટિકિટ પરનો reference ફરીથી લખે છે, સૌથી જૂની પહેલા. મુખ્યત્વે બીજી સિસ્ટમમાંથી ખસ્યા પછી તરત જ ઉપયોગી, જ્યારે તમે બધું સુસંગત દેખાય તેમ ઈચ્છો છો.',
            'renumber_safety' => '<strong>જૂના reference કામ કરવાનું ચાલુ રાખે છે.</strong> ટિકિટને ક્યારેય મળેલો દરેક નંબર યાદ રખાય છે, એટલે જૂનાનો ઉલ્લેખ કરતા ઈમેઈલનો જવાબ હજુ પણ સાચી ટિકિટ પર પહોંચે છે &mdash; બરાબર જેમ ટિકિટ મર્જ થાય ત્યારે થાય છે. રિટાયર થયેલો નંબર બીજી ટિકિટને ક્યારેય આપવામાં આવતો નથી. જોકે, આ પૂર્વવત કરી શકાય તેવું નથી, એટલે પહેલા પ્રિવ્યૂ જુઓ.',
