            'snooze_hour_help' => '"Tomorrow" અથવા "Next week" સુધી snooze કરેલી ટિકિટ પાછી આવવાનો સમય. દરેક વિશ્લેષકના પોતાના ટાઈમઝોનમાં વંચાય છે, એટલે ઝોન પર ફેલાયેલા ડેસ્કને દરેકને પોતાની સવાર મળે છે.',
            'collapse_heading' => 'લાંબા મેસેજ',
            'collapse_desc' => 'લાંબા ઈમેઈલ તમે ટિકિટ ખોલી જે વાંચવા માંગતા હતા તેને દબાવી દે છે. નીચેની મર્યાદા કરતાં ઊંચા મેસેજ Show more લિંક સાથે ટૂંકા કરાય છે. કંઈ ડિલીટ થતું નથી — સંપૂર્ણ મેસેજ હંમેશા એક ટેપ દૂર છે.',
            'collapse_enabled_label' => 'લાંબા મેસેજ ટૂંકા કરો',
            'collapse_lines_label' => 'આનાથી વધુ ઊંચા મેસેજ ટૂંકા કરો, લગભગ',
            'collapse_lines_help' => 'લાઈન. મર્યાદા કરતાં થોડું જ વધુ મેસેજ એમ જ રહેવા દેવાય છે, જેથી ફક્ત બે શબ્દો માટે લિંક ક્યારેય દેખાતી નથી.',
            'collapse_newest_label' => 'સૌથી નવો મેસેજ હંમેશા સંપૂર્ણ બતાવો',
            'collapse_newest_help' => 'જે મેસેજ વાંચવા તમે આવ્યા છો તે ક્યારેય ટૂંકો કરાતો નથી.',
            'collapse_quoted_label' => 'ક્વોટ કરેલો ઈતિહાસ ટૂંકો કરો',
            'collapse_quoted_help' => 'નીચે લાંબી ક્વોટ કરેલી ચેઈન સાથેનો ટૂંકો જવાબ કોઈપણ લાઈન કાઉન્ટથી સંક્ષિપ્ત હોય છે અને છતાં અવાચ્ય હોય છે, એટલે ક્વોટ કરેલો ઈતિહાસ અલગથી ટૂંકો કરાય છે.',
            'collapse_remember_label' => 'મેં શું ખોલ્યું તે યાદ રાખો',
            'collapse_remember_help' => 'તમે વિસ્તૃત કરેલા મેસેજ આ ડિવાઈસ પર વિસ્તૃત જ રહે છે, એટલે થ્રેડ પર કામ કરવું દરેક રિફ્રેશ પર પોતાની જાતે પૂર્વવત થતું નથી.',
            'group_older_label' => 'જૂના મેસેજને ફોલ્ડ કરો',
            'group_older_help' => 'નીચેના નંબરથી આગળ, જૂના મેસેજ એક લાઈનમાં ફોલ્ડ થાય છે જે તમે ખોલી શકો છો. લાંબી ટિકિટ એ લાંબા મેસેજ કરતાં અલગ સમસ્યા છે.',
            'group_show_label' => 'આટલા તાજેતરના મેસેજ ખુલ્લા રાખો',
            'flag_duplicates_label' => 'પહેલા આવી ગયેલા મેસેજ તરફ ધ્યાન દોરો',
            'flag_duplicates_help' => 'ફરીથી મોકલેલું, ડુપ્લિકેટ ડિલિવરી અથવા મૂળને પાછું લાવતો બાઉન્સ, તે કયા મેસેજ સાથે મેચ થાય છે તેની નોંધ સાથે ફોલ્ડ કરાય છે. કંઈ ડિલીટ થતું નથી.',
            'ai_heading' => 'AI વાંચન સહાય',
            'ai_desc' => 'વૈકલ્પિક, અને તમે ચાલુ ન કરો ત્યાં સુધી બંધ: આ પેજ પરની બીજી દરેક વસ્તુથી વિપરીત આ તમારો પોતાનો AI પ્રોવાઇડર વાપરે છે અને દરેક ઉપયોગ માટે પૈસા લે છે. પ્રોવાઇડર, મોડેલ અને API key Reply cleanup ટેબ પર એકવાર ગોઠવાય છે. AI જે લખે તે ટિકિટને ક્યારેય બદલતું નથી — વાતચીત બરાબર જ્યાં છે ત્યાં જ, સંપૂર્ણ રહે છે.',
            'ai_summary_label' => 'દરેક ટિકિટની ટોચે ટૂંકો AI સાર રાખો',
            'ai_summary_help' => 'ટિકિટ ક્યાં ઊભી છે તે કહેતી થોડી લાઈન, વિનંતી પર લખાય છે અને અપડેટેડ રખાય છે. તે હંમેશા બતાવે છે કે ક્યારે લખાયું, કેટલું વાંચ્યું, અને ત્યારથી વાતચીત કેટલી આગળ વધી છે. દરેક વર્ઝન રખાય છે, એટલે ખરાબ સાર ક્યારેય સારા સારને નષ્ટ કરતો નથી.',
            'ai_auto_label' => 'આટલા નવા મેસેજ પછી તેને આપોઆપ રિફ્રેશ કરો',
            'ai_auto_help' => '0 નો અર્થ ક્યારેય નહીં — પછી Refresh બટન જ એકમાત્ર રસ્તો છે, અને કોઈ પૂછ્યા વગર ક્યારેય કંઈ ચાર્જ થતું નથી. રિફ્રેશ ફક્ત ત્યારે જ થાય છે જ્યારે વિશ્લેષક ટિકિટ ખોલે છે, એટલે વ્યસ્ત ક્યૂ જેને કોઈ વાંચતું નથી તેનો કોઈ ખર્ચ થતો નથી.',
            'ai_max_label' => 'વાંચવાના મેસેજ',
            'ai_max_help' => 'સાર કેટલું પાછળ વાંચે છે. લાંબી ટિકિટ તેના સૌથી તાજેતરના છેડેથી વંચાય છે, અને સાર તે કહે છે, જે શરૂઆત તેણે ક્યારેય જોઈ નથી તેનું વર્ણન કરવાને બદલે.',
            'ai_notes_label' => 'તેને આંતરિક નોંધ વાંચવા દો',
            'ai_notes_help' => 'આંતરિક નોંધ ઘણીવાર ખરેખર શું અજમાવ્યું તે ધરાવે છે. તે ગમે તે રીતે ફક્ત સ્ટાફ માટે જ છે — સાર ક્યારેય વિનંતીકર્તાને બતાવાતો નથી — પણ જો તમારા ડેસ્ક પરની નોંધમાં એવી વસ્તુ હોય જે તેને છોડવી ન જોઈએ તો આને બંધ કરો.',
            'ai_read_label' => 'ટિકિટ પર "Read it for me" ઓફર કરો',
            'ai_read_help' => 'એક બટન જે આખી ટિકિટ વાંચે છે અને તમને તેની બ્રીફિંગ આપે છે: શું થયું, શું ઉકેલાયું નથી, અને પછી શું કરવું જોઈએ. પૂછવા પર અને એકવાર વંચાય છે, ક્યાંય સંગ્રહાતું નથી.',
            'reopen_help' => 'જ્યાં પણ વિનંતીકર્તા પાછો આવે ત્યાં લાગુ પડે છે — સેલ્ફ-સર્વિસ પોર્ટલ, તમારા નોટિફિકેશન ઈમેઈલનો જવાબ, WhatsApp અથવા વેબ ચેટ. ટિકિટ તમારી પહેલી ઓપન સ્થિતિમાં પાછી જાય છે. ફક્ત બંધ તરીકે ચિહ્નિત સ્થિતિમાંની ટિકિટ પર જ અસર થાય છે (તે કઈ છે તે Statuses હેઠળ સેટ કરો).',
        ],
        'privacy' => [
            'third_party_label' => 'વિનંતીકર્તા સિવાયના કોઈને મોકલેલા મેસેજ',
            'opt_hide' => 'વિનંતીકર્તાથી તેમને છુપાવો',
            'opt_hide_help' => 'મેસેજ અને તેના જોડાણો વિનંતીકર્તાના પોર્ટલમાં બિલકુલ દેખાતા નથી. ભલામણ કરેલ: મોટાભાગના લોકો ધારે છે કે ટિકિટને સપ્લાયરને ફોરવર્ડ કરવી ખાનગી છે.',
            'opt_no_attachments' => 'મેસેજ બતાવો, પણ તેના જોડાણો નહીં',
            'opt_no_attachments_help' => 'વિનંતીકર્તા જોઈ શકે છે કે તમે બીજા કોઈનો સંપર્ક કર્યો અને શું લખાયું, પણ કોઈ જોડેલી ફાઈલ ડાઉનલોડ કરી શકતા નથી.',
            'opt_show' => 'બધું બતાવો',
            'opt_show_help' => 'વિનંતીકર્તા આખી ટિકિટ બરાબર તમારા વિશ્લેષકોની જેમ જુએ છે, ફોરવર્ડ અને થર્ડ-પાર્ટી જવાબો સહિત. આ સેટિંગ અસ્તિત્વમાં આવ્યા પહેલાનું વર્તન હતું.',
            'always_visible_note' => '<strong>વિનંતીકર્તાને હંમેશા દેખાય:</strong> તેમના પોતાના મેસેજ, અને તેમને સંબોધિત કોઈપણ જવાબ. <strong>ક્યારેય દેખાય નહીં:</strong> આંતરિક નોંધ — આ સેટિંગને ધ્યાનમાં લીધા વગર તે પોર્ટલથી છુપાયેલી છે. WhatsApp અને વેબ ચેટ પરના મેસેજ હંમેશા બતાવાય છે, કારણ કે તે વાતચીત વ્યાખ્યા પ્રમાણે વિનંતીકર્તા અને તમારા ડેસ્ક વચ્ચેની છે.',
            'timezone' => 'ટાઈમઝોન',
            'timezone_help' => 'સિસ્ટમમાં દરેક જગ્યાએ તારીખ અને સમય બતાવવા વપરાય છે.',
        ],
        'reply_cleanup' => [
            'intro1' => 'જ્યારે વિશ્લેષક ટિકિટ કમ્પોઝ મોડલમાં કાચો જવાબ ટાઈપ કરે, ત્યારે <strong>✨ Cleanup</strong> બટન તેને યોગ્ય રીતે ફોર્મેટ કરેલા ઈમેઈલ તરીકે ફરીથી લખશે — "Dear [name]," ગ્રીટિંગ ઉમેરીને, વ્યાકરણ સુધારીને, નીચે તમે પસંદ કરેલો ટોન લાગુ કરીને, અને "Kind regards," થી સાઈન ઓફ કરીને. તે ટેકનિકલ વિગતો ઉપજાવશે <strong>નહીં</strong> અથવા કન્ટેન્ટ પેડ કરશે નહીં.',
            'intro2' => 'આ ફીચર પોતાની Anthropic API key વાપરે છે (RFP AI અને Knowledge AI થી અલગ) જેથી તેનો ઉપયોગ Anthropic બિલિંગ ડેશબોર્ડ પર અલગ લાઈન તરીકે દેખાય.',
            'tone' => 'ટોન',
            'tone_friendly' => 'Friendly (ડિફોલ્ટ)',
            'tone_formal' => 'Formal',
            'tone_brief' => 'Brief',
            'tone_help' => 'જ્યાં સુધી અહીં ન બદલાય ત્યાં સુધી દરેક cleanup પર લાગુ થાય છે.',
            'custom_label' => 'કસ્ટમ સૂચનાઓ <span style="color: #999; font-weight: normal;">(વૈકલ્પિક)</span>',
            'custom_placeholder' => 'દા.ત. હંમેશા \'Many thanks,\' થી સાઈન ઓફ કરો&#10;કંપનીને \'BillCorp\' તરીકે ઉલ્લેખો&#10;સમગ્રમાં British English સ્પેલિંગ વાપરો',
            'custom_help' => 'જમણી બાજુ બતાવેલા સિસ્ટમ પ્રોમ્પ્ટમાં ઉમેરાય છે. સંસ્થા-વિશિષ્ટ ફેરફારો (સાઈન-ઓફ ભિન્નતા, કંપનીનું નામ, ભાષા પસંદગી) માટે આનો ઉપયોગ કરો. કડક સેફ્ટી નિયમો અને આઉટપુટ ફોર્મેટ હજુ પણ પ્રાધાન્ય લેશે.',
            'prompt_summary' => 'સિસ્ટમ પ્રોમ્પ્ટ જુઓ (ફક્ત વાંચી શકાય)',
            'prompt_panel_intro' => 'આ દરેક cleanup પર Claude ને મોકલવામાં આવતું સંપૂર્ણ સિસ્ટમ પ્રોમ્પ્ટ છે. ગ્રીટિંગનું નામ દરેક ટિકિટ પ્રમાણે બદલાય છે; ટોન ડાબી બાજુ તમારી પસંદગી દર્શાવે છે. તમારી કસ્ટમ સૂચનાઓ (જો હોય તો) runtime પર છેલ્લે ઉમેરાય છે — તે અહીં બતાવાતી નથી, તેમને ડાબી બાજુના ટેક્સ્ટએરિયામાં સંપાદિત કરો.',
