        'overview' => [
            'heading' => 'ઝાંખી',
            'intro' => 'ટિકિટ મોડ્યુલ તમારા IT સર્વિસ ડેસ્કનું કેન્દ્ર છે. તે સપોર્ટ વિનંતીઓ, ઘટનાઓ અને સેવા કાર્યોનું સંચાલન કરવા માટે એક પરિચિત ઈમેલ-ક્લાયન્ટ જેવું ઇન્ટરફેસ આપે છે. ટિકિટો એન્ડ યુઝર્સ તરફથી ઈમેલ મારફતે અથવા મેન્યુઅલ રીતે બનાવવાથી આવે છે, અને વિશ્લેષકો ફોલ્ડર, પ્રાથમિકતાઓ અને SLA ટાઈમર્સનો ઉપયોગ કરીને તેમના પર કામ કરે છે &mdash; રિસ્પોન્સિવ IT સપોર્ટ પૂરો પાડવા માટે જરૂરી બધું જ.',
            'card_inbox_title' => 'ઇનબોક્સ',
            'card_inbox_body' => 'ઈમેલ ક્લાયન્ટ પર આધારિત ફોલ્ડર-આધારિત ઇનબોક્સ. મારી ટિકિટો, અસોંપાયેલ, બધી ખુલ્લી અને બંધ ફોલ્ડર બ્રાઉઝ કરો. સંપૂર્ણ વિગતો, ઇતિહાસ અને ક્રિયાઓ સાથે રીડિંગ પેન ખોલવા માટે કોઈપણ ટિકિટ પર ક્લિક કરો.',
            'card_dashboard_title' => 'ડેશબોર્ડ',
            'card_dashboard_body' => 'કસ્ટમાઇઝ કરી શકાય તેવા Chart.js વિજેટ્સ સાથે વ્યક્તિગત ડેશબોર્ડ બનાવો. બાર, પાઇ, ડોનટ અને લાઇન ચાર્ટ વડે ટિકિટ વોલ્યુમ, રિસ્પોન્સ ટાઈમ, કેટેગરી બ્રેકડાઉન અને વિશ્લેષક વર્કલોડને વિઝ્યુઅલાઈઝ કરો.',
            'card_calendar_title' => 'કૅલેન્ડર',
            'card_calendar_body' => 'તેમની બનાવ્યાની, નિયત અથવા ઉકેલાયેલ તારીખોના આધારે ટિકિટોને કૅલેન્ડર ગ્રિડ પર જુઓ. મોડી પડેલી આઇટમ્સ ઝડપથી શોધો અને એક નજરમાં સમગ્ર ટિકિટ ચિત્ર જોઈને તમારું અઠવાડિયું આયોજિત કરો.',
