            'field_my' => '<strong>મારી ટિકિટો</strong> &mdash; તમને સોંપાયેલ ટિકિટો. આ તમારી અંગત ક્યૂ છે અને દરરોજ શરૂ કરવા માટેની શ્રેષ્ઠ જગ્યા છે.',
            'field_unassigned' => '<strong>અસોંપાયેલ</strong> &mdash; આવેલી પણ હજુ સુધી કોઈ વિશ્લેષકને ન સોંપાયેલ ટિકિટો. માલિકી લેવા માટે અહીંથી આઇટમ્સ પસંદ કરો.',
            'field_all_open' => '<strong>બધી ખુલ્લી</strong> &mdash; જેની માલિકી કોઈની પણ હોય, હજુ સુધી બંધ ન થયેલી દરેક ટિકિટ. એકંદર વોલ્યુમ પર નજર રાખતા મેનેજર્સ અને ટીમ લીડ્સ માટે ઉપયોગી.',
            'field_closed' => '<strong>બંધ</strong> &mdash; ઉકેલાયેલ ટિકિટો. જ્યારે તમારે ભૂતકાળના ઉકેલનો સંદર્ભ લેવો હોય અથવા કોઈ સમસ્યા ફરીથી ખોલવી હોય ત્યારે અહીં શોધો.',
            'field_dept' => '<strong>વિભાગ ફોલ્ડર</strong> &mdash; વિભાગ પ્રમાણે જૂથબદ્ધ ટિકિટો (દા.ત. IT, HR, ફાઇનાન્સ). વિભાગો Settings માં ગોઠવવામાં આવે છે અને આપમેળે સબ-ફોલ્ડર તરીકે દેખાય છે.',
            'switch_heading' => '<strong>વિભાગ અને વિશ્લેષક જૂથબદ્ધ વચ્ચે સ્વિચ કરવું</strong>',
            'switch_body' => 'ફોલ્ડર પેનલની ટોચે એક નાનું ટૂ-બટન ટૉગલ સમાન ડેટાના બે વ્યૂ વચ્ચે સ્વિચ કરે છે. <strong>વિભાગ</strong> જૂથબદ્ધ (ડિફોલ્ટ) દરેક વિભાગ હેઠળ સ્થિતિ સબ-ફોલ્ડર સાથે ટિકિટો યાદીબદ્ધ કરે છે; <strong>વિશ્લેષક</strong> જૂથબદ્ધ તેને ઉલટાવે છે જેથી દરેક ટોપ-લેવલ ફોલ્ડર સ્થિતિ સબ-ફોલ્ડર સાથે એક વિશ્લેષકની અંગત ક્યૂ દર્શાવે. <strong>અસોંપાયેલ</strong> ફોલ્ડર દરેક વ્યૂમાં કૉન્ટેક્સ્ટ-અવેર છે &mdash; વિભાગ વ્યૂમાં તે કોઈ વિભાગ સેટ ન હોય તેવી ટિકિટો યાદીબદ્ધ કરે છે; વિશ્લેષક વ્યૂમાં તે કોઈ સોંપાયેલ ન હોય તેવી ટિકિટો યાદીબદ્ધ કરે છે &mdash; જેથી તમે હંમેશા જોઈ શકો કે શું હાથમાં લેવાની જરૂર છે. તમારી પસંદગી પ્રતિ-વિશ્લેષક સાચવવામાં આવે છે જેથી દરેક ટીમ સભ્ય સેશન્સ દરમિયાન પોતાનો પસંદગીનો વ્યૂ જાળવી રાખે.',
            'row_name' => 'દરેક પંક્તિ ટિકિટ સંદર્ભ અને પછી એક નામ બતાવે છે. ડિફોલ્ટ રીતે તે <strong>ટિકિટ ઉઠાવનાર વ્યક્તિ</strong> છે, અને તે ટિકિટના સમગ્ર જીવનકાળ દરમિયાન એ જ રહે છે. જો તમે તેના બદલે તાજેતરનો સંદેશ મોકલનાર જોવા માંગતા હો &mdash; જે તમે જવાબ આપ્યા પછી તમારું પોતાનું મેઈલબોક્સ બની જાય છે &mdash; તો <strong>Settings &rarr; Row display</strong> હેઠળ <strong>ટિકિટ નંબરની બાજુમાં નામ</strong> બદલો, જ્યાં તમે નામ છુપાવીને ફક્ત સંદર્ભ પણ છોડી શકો છો. તે ટેબ તમારી પોતાની સેટિંગ છે: તે બીજા કોઈ માટે કંઈ બદલતી નથી.',
            'tip' => 'યાદીમાંની કોઈપણ ટિકિટ પર ક્લિક કરીને તેને રીડિંગ પેનમાં લોડ કરો. ત્યાંથી તમે ફીલ્ડ અપડેટ કરી શકો છો, ટિપ્પણીઓ ઉમેરી શકો છો, ઈમેલ દ્વારા જવાબ આપી શકો છો, અથવા ફાઇલો જોડી શકો છો &mdash; ઇનબોક્સમાંથી બહાર ગયા વિના જ.',
        ],
        'faster' => [
            'heading' => 'ઝડપથી કામ કરવું',
            'intro' => 'ચાર બાબતો જે વ્યસ્ત સવારને સંભાળી શકાય તેવી બનાવે છે: સાચવેલા જવાબો, એકસાથે અનેક ટિકિટો પર કાર્યવાહી કરવી, અને વાતચીતોને તેમની યોગ્ય જગ્યાએ મૂકવી.',
            'templates_heading' => 'તૈયાર જવાબો',
            'templates_body' => 'તમે સતત એ જ મુઠ્ઠીભર જવાબો મોકલો છો. એકવાર લખો, પછી તેને તમારા કર્સર પર મૂકવા માટે રિપ્લાય એડિટરની ઉપર <strong>Templates</strong> પર ક્લિક કરો &mdash; તે તમે પહેલેથી ટાઈપ કરેલા ટેક્સ્ટને બદલવાને બદલે તેમાં ઉમેરાય છે. Templates રિચ ટેક્સ્ટ છે અને ઓટોમેટેડ ઈમેલ્સ જેવા જ <code>[merge_code]</code> પ્લેસહોલ્ડર્સને સપોર્ટ કરે છે, જેથી <code>[requester_first_name]</code> તમે તેને ઇન્સર્ટ કરો ત્યારે વાસ્તવિક નામ બની જાય છે.',
            'templates_team' => '<strong>ટીમ ટેમ્પલેટ્સ</strong> &mdash; બધા સાથે શેર કરેલ, Settings &rarr; Reply templates માં સેટ કરેલ.',
            'templates_mine' => '<strong>તમારા પોતાના</strong> &mdash; <em>Save draft as template</em> વડે ડ્રાફ્ટ સાચવો. ફક્ત તમારા માટે ખાનગી, અને કોઈ પરવાનગીની જરૂર નથી.',
            'templates_tip' => 'ટેમ્પલેટને તેના શબ્દો માટે નહીં, પરિસ્થિતિ માટે નામ આપો ("Printer offline &mdash; first steps"). સવારે 9 વાગ્યે તમે એ જ શોધતા હશો.',
            'select_heading' => 'અનેક ટિકિટો પસંદ કરવી',
            'select_body' => 'ટિકિટ યાદી Outlook અથવા File Explorer જેવી કામ કરે છે. કોઈ ચેકબૉક્સ નથી.',
            'key_click' => 'ક્લિક',
            'key_click_d' => 'એક પસંદ કરો અને તેને ખોલો',
            'key_ctrl' => 'Ctrl+ક્લિક',
            'key_ctrl_d' => 'એક ઉમેરો અથવા દૂર કરો, બાકીનાને એમ જ રહેવા દો',
            'key_shift' => 'Shift+ક્લિક',
            'key_shift_d' => 'તમે છેલ્લે ક્લિક કર્યું હતું ત્યાંથી આખો બ્લોક પસંદ કરો',
            'key_kb' => 'કીબોર્ડ',
            'key_kb_d' => 'ખસેડવા માટે એરો, વિસ્તારવા માટે Shift+એરો, છૂટીછવાઈ ટિકિટો પસંદ કરવા માટે Ctrl+એરો અને Space, બધા માટે Ctrl+A, સાફ કરવા માટે Escape',
            'select_actions' => 'અનેક પસંદ કરેલ હોય ત્યારે, બધા માટે એકસાથે સ્થિતિ, પ્રાથમિકતા, વિભાગ, પ્રકાર અથવા સોંપાયેલ સેટ કરવા માટે <strong>તેમાંથી કોઈપણ પર રાઇટ-ક્લિક કરો</strong> &mdash; અથવા આખા સેટને ફોલ્ડર પર ડ્રેગ કરો. અનેક પસંદ કરેલ હોય ત્યારે સ્ક્રીન શું બતાવે છે તે તમારી પસંદગી છે, એકાઉન્ટ મેનૂમાં Preferences હેઠળ.',
            'select_tip' => 'તમારી પસંદગીમાં <em>ન હોય</em> તેવી ટિકિટ પર રાઇટ-ક્લિક કરવાથી પસંદગી સાફ થઈ જાય છે અને ફક્ત તે એક જ ટિકિટ પર ટાર્ગેટ થાય છે. આ ઇરાદાપૂર્વક છે &mdash; તમે એવા સેટ પર ક્યારેય કાર્યવાહી કરી શકતા નથી જેને તમે છોડી ચૂક્યા હોવાનું માનતા હતા.',
            'merge_heading' => 'ડુપ્લિકેટ્સ મર્જ કરવા',
            'merge_body' => 'બે લોકોએ એક જ આઉટેજની જાણ કરી? ટિકિટો પસંદ કરો, રાઇટ-ક્લિક કરો, <strong>Merge</strong>. વાતચીતો એકસાથે આવે છે, અને જો તમારી પાસે AI પ્રોવાઇડર ગોઠવેલ હોય તો FreeITSM દરેકે શું પૂછ્યું અને શું પહેલેથી કરવામાં આવ્યું છે તેની ટૂંકી બ્રીફિંગ લખે છે, જેથી જે કોઈ તે ઉપાડે તેને ચાર થ્રેડ વાંચવા ન પડે.',
            'merge_tip' => 'કંઈ પણ ક્યારેય કાઢી નાખવામાં આવતું નથી. મર્જ થયેલી ટિકિટ પોતાનો સંદર્ભ જાળવી રાખે છે, શોધી શકાય તેવી રહે છે, ક્યાં ગઈ તે બતાવે છે &mdash; અને તેના વિશેના જૂના ઈમેલનો જવાબ આપતો ગ્રાહક હજુ પણ તમારા સુધી પહોંચે છે.',
            'split_heading' => 'ટિકિટ વિભાજિત કરવી',
            'split_body' => 'તેનાથી ઉલટું કામ. જ્યારે કોઈ વાતચીતની વચ્ચે બીજી, અસંબંધિત બાબત ઉઠાવે, ત્યારે તે સંદેશ પર <strong>Split</strong> પર ક્લિક કરો (અથવા સંદેશની હેડર પર રાઇટ-ક્લિક કરો). તે એક નવી ટિકિટમાં ખસે છે, ઈચ્છા મુજબ તેની સાથે દરેક નવા સંદેશને લઈ જાય છે, અને મૂળ ટિકિટમાં તે ક્યાં ગયા તે બતાવતું માર્કર રહે છે.',
            'split_tip' => 'નવી ટિકિટને યોગ્ય વિષય આપો. તે ડિફોલ્ટ રીતે ખસેડેલા સંદેશના વિષય પર જાય છે, જે સામાન્ય રીતે <em>જૂની</em> સમસ્યાનો "RE:" હોય છે.',
            'undo_heading' => 'તમારો વિચાર બદલાયો',
            'undo_body' => 'બંનેને ટિકિટ પરના બેનરથી પૂર્વવત્ કરી શકાય છે. એકવાર કોઈએ નવી ટિકિટ પર જવાબ આપ્યો હોય, નોંધ ઉમેરી હોય અથવા સમય લોગ કર્યો હોય, પછી <strong>split</strong> ને પૂર્વવત્ કરવાનો ઇનકાર થાય છે &mdash; તમને બરાબર જણાવવામાં આવે છે કે શું અડચણરૂપ છે. <strong>merge</strong> ને પૂર્વવત્ કરવાથી ટિકિટને તેના સંદેશ, નોંધો અને લોગ કરેલો સમય પાછો મળે છે અને તે બરાબર જેમ હતી તેમ ફરીથી ખૂલે છે, પરંતુ મર્જ પછી બીજી ટિકિટ પર લખેલા જવાબો ત્યાં જ રહે છે.',
        ],
        'working' => [
            'heading' => 'ટિકિટ સાથે કામ કરવું',
            'intro' => 'દરેક સપોર્ટ વિનંતી એક જીવનચક્રને અનુસરે છે: તે બનાવવામાં આવે છે, ટ્રાયેજ થાય છે, તેના પર કામ થાય છે, અને છેવટે ઉકેલાય છે. ટિકિટ મોડ્યુલ તમને શરૂઆતના લોગિંગથી લઈને બંધ થવા સુધીના દરેક તબક્કાને અસરકારક રીતે સંચાલિત કરવા માટેના સાધનો આપે છે.',
            'creating_heading' => '<strong>નવી ટિકિટ બનાવવી</strong>',
            'step1' => '<strong>New પર ક્લિક કરો</strong> &mdash; ઇનબોક્સ ટૂલબારમાંથી નવી ટિકિટ મોડલ ખોલો. વિનંતી કરનારનું નામ અને ઈમેલ સરનામું દાખલ કરો જેથી તેમને અપડેટ્સ મળી શકે.',
            'step2' => '<strong>વિષય સેટ કરો</strong> &mdash; સમસ્યાનો સ્પષ્ટ, સંક્ષિપ્ત સારાંશ લખો. આ ટિકિટ યાદીમાં અને એન્ડ યુઝરને મોકલાયેલ કોઈપણ ઈમેલ સૂચનાઓમાં દેખાય છે.',
            'step3' => '<strong>વિભાગ, પ્રકાર અને પ્રાથમિકતા પસંદ કરો</strong> &mdash; યોગ્ય વિભાગ, ટિકિટ પ્રકાર (દા.ત. Incident, Service Request), અને પ્રાથમિકતા સ્તર પસંદ કરો. આ ફીલ્ડ SLA ટાઈમર્સ અને રૂટિંગ નિયમો ચલાવે છે.',
            'step4' => '<strong>વર્ણન ઉમેરો</strong> &mdash; રિચ ટેક્સ્ટ એડિટરનો ઉપયોગ કરીને સમસ્યાની સંપૂર્ણ વિગતો આપો. પુનરાવર્તન કરવાના પગલાં, ભૂલ સંદેશા, અને ઉકેલ કરનાર વિશ્લેષકને જરૂરી કોઈપણ સંબંધિત સંદર્ભ શામેલ કરો.',
            'step5' => '<strong>સાચવો</strong> &mdash; ટિકિટ એક અનન્ય સંદર્ભ નંબર સાથે બનાવવામાં આવે છે અને યોગ્ય ફોલ્ડરમાં દેખાય છે. પ્રાથમિકતાના આધારે SLA ઘડિયાળ તરત જ શરૂ થાય છે.',
            'editing_heading' => '<strong>ટિકિટોનું સંપાદન અને સંચાલન</strong>',
            'editing_body' => 'એકવાર ટિકિટ અસ્તિત્વમાં આવે, પછી તમે રીડિંગ પેનમાંથી કોઈપણ ફીલ્ડ અપડેટ કરી શકો છો. મુખ્ય ફીલ્ડમાં શામેલ છે:',
            'card_status_title' => 'સ્થિતિ',
            'card_status_body' => 'ટિકિટના જીવનચક્રને ટ્રૅક કરો: New, Open, In Progress, Pending, Resolved, Closed',
            'card_priority_title' => 'પ્રાથમિકતા',
            'card_priority_body' => 'તાકીદ અને અસર સેટ કરો: Critical, High, Medium, Low. દરેક સ્તરનું પોતાનું SLA લક્ષ્ય છે',
            'card_category_title' => 'શ્રેણી',
            'card_category_body' => 'સમસ્યાના પ્રકારનું વર્ગીકરણ કરો: Hardware, Software, Network, Access, General. રિપોર્ટિંગ માટે ઉપયોગી',
            'card_analyst_title' => 'સોંપાયેલ વિશ્લેષક',
            'card_analyst_body' => 'ટિકિટ ઉકેલવા માટે જવાબદાર વ્યક્તિ. પુનઃસોંપણી પ્રવૃત્તિ ટ્રેલમાં લોગ થાય છે',
            'card_enduser_title' => 'એન્ડ યુઝર',
            'card_enduser_body' => 'વિનંતી ઉઠાવનાર વ્યક્તિ. હાલના યુઝર રેકોર્ડ સાથે લિંક કરવા માટે નામ અથવા ઈમેલ દ્વારા શોધો',
            'card_dept_title' => 'વિભાગ',
            'card_dept_body' => 'ટિકિટોને યોગ્ય ટીમ પર રૂટ કરો. વિભાગો ફોલ્ડર જૂથબદ્ધ અને ડેશબોર્ડ ફિલ્ટર ચલાવે છે',
            'flow_new' => 'New',
            'flow_in_progress' => 'In Progress',
            'flow_resolved' => 'Resolved',
            'flow_closed' => 'Closed',
            'triage_heading' => '<strong>ડ્રેગ અને ડ્રોપ દ્વારા ટ્રાયેજ</strong>',
            'triage_body' => 'ટિકિટને ટ્રાયેજ કરવા માટે તેને ખોલવાની જરૂર નથી. એક જ હલચલમાં ફીલ્ડ અપડેટ કરવા માટે ટિકિટ યાદીમાંથી કોઈપણ પંક્તિને ફોલ્ડર પર ડ્રેગ કરો:',
            'triage_dept' => '<strong>વિભાગ વ્યૂ</strong> &mdash; પુનઃસોંપણી માટે વિભાગ ફોલ્ડર પર ડ્રોપ કરો, બંનેને એકસાથે અપડેટ કરવા માટે વિભાગ હેઠળના સ્થિતિ સબ-ફોલ્ડર પર ડ્રોપ કરો, વિભાગ સાફ કરવા માટે <strong>અસોંપાયેલ</strong> પર ડ્રોપ કરો.',
            'triage_analyst' => '<strong>વિશ્લેષક વ્યૂ</strong> &mdash; તે વિશ્લેષકને માલિક તરીકે સોંપવા માટે વિશ્લેષકના ફોલ્ડર પર ડ્રોપ કરો (બંને <code>assigned_analyst_id</code> અને <code>owner_id</code> સેટ કરે છે જેથી રીડિંગ પેનમાં Owner ફીલ્ડ સિંકમાં રહે), બંનેને અપડેટ કરવા માટે સ્થિતિ સબ-ફોલ્ડર પર ડ્રોપ કરો, સોંપાયેલ સાફ કરવા માટે <strong>અસોંપાયેલ</strong> પર ડ્રોપ કરો.',
            'triage_spring' => '<strong>સ્પ્રિંગ-લોડેડ ફોલ્ડર</strong> &mdash; ડ્રેગ દરમિયાન સંકોચાયેલા ફોલ્ડર પર હોવર કરો અને તે આપમેળે વિસ્તરે છે (Outlook-સ્ટાઈલ) જેથી પહેલા ડ્રોપ કર્યા વિના કોઈપણ નેસ્ટેડ સ્થિતિ સુધી પહોંચી શકાય.',
            'fullscreen_heading' => '<strong>ફુલ-સ્ક્રીન વ્યૂ</strong>',
            'fullscreen_body' => 'જ્યારે તમારે એક જ ટિકિટ પર ધ્યાન કેન્દ્રિત કરવું હોય &mdash; લાંબી વાતચીત, જટિલ ચેન્જ, વિગતવાર જવાબ ડ્રાફ્ટ કરવો &mdash; ત્યારે ફુલ-સ્ક્રીન વ્યૂ પર સ્વિચ કરો. ફોલ્ડર યાદી અને ટિકિટ યાદી અદૃશ્ય થાય છે, વાતચીત ઉપલબ્ધ પહોળાઈ ભરે છે, અને પ્રોપર્ટીઝ (Department, Type, Status, Origin, First Time Fix, IT Training, Owner) જમણી બાજુ એક વર્ટિકલ સાઈડબારમાં ખસે છે.',
            'fullscreen_max' => '<strong>Maximize આઇકોન</strong> &mdash; ટિકિટ વિષય લાઇનના જમણા છેડે નાનો આઇકોન. ફુલ-સ્ક્રીનમાં જવા માટે ક્લિક કરો; 3-પેન લેઆઉટ પર પાછા જવા માટે ફરીથી ક્લિક કરો.',
            'fullscreen_dbl' => '<strong>પંક્તિ પર ડબલ-ક્લિક કરો</strong> &mdash; યાદીમાંની કોઈપણ ટિકિટને સીધી ફુલ-સ્ક્રીનમાં ખોલવા માટે ડબલ-ક્લિક કરો, Outlook-સ્ટાઈલ "ખરેખર આ ખોલો" જેશ્ચર.',
            'fullscreen_sticks' => '<strong>પસંદગીઓ વચ્ચે જળવાઈ રહે છે</strong> &mdash; એકવાર તમે ફુલ-સ્ક્રીનમાં હો, પછી આગલી ટિકિટ પર સ્વિચ કરવાથી તમે ત્યાં જ રહો છો. કોઈ ટિકિટ પસંદ કર્યા વગર ફ્રેશ પેજ રિલોડ (F5) ડિફોલ્ટ 3-કૉલમ લેઆઉટ પર પાછા લાવે છે, જેથી તમે ફોલ્ડર યાદી છુપાયેલી હોવાથી ફસાયેલા ન રહી શકો.',
            'rightclick_heading' => '<strong>ઝડપી ક્રિયાઓ માટે રાઇટ-ક્લિક</strong>',
            'rightclick_body' => 'કૉન્ટેક્સ્ટ મેનૂ ખોલવા માટે યાદીમાંની કોઈપણ ટિકિટ પર રાઇટ-ક્લિક કરો. મેનૂ ટોચ પર ટિકિટ સંદર્ભ બતાવે છે જેથી તમે જાણો કે તમે શેના પર કાર્યવાહી કરી રહ્યા છો, અને દરેક ક્રિયા રીડિંગ પેનમાં હાલમાં ખુલેલી વસ્તુ <em>બદલ્યા વિના</em> રાઇટ-ક્લિક કરેલી ટિકિટ પર જ કામ કરે છે &mdash; જ્યારે તમે ટિકિટ A વાંચી રહ્યા હો અને તમારી જગ્યા ગુમાવ્યા વિના ટિકિટ B ને ટ્રાયેજ કરવાની જરૂર હોય ત્યારે ઉપયોગી.',
            'rightclick_status' => '<strong>Set status &rarr;</strong> &mdash; દરેક સક્રિય સ્થિતિને તેના રંગ સ્વોચ સાથે યાદીબદ્ધ કરતું ફ્લાયઆઉટ સબમેનૂ. જો તમે ખુલેલી ટિકિટ પર જ રાઇટ-ક્લિક કરી રહ્યા હો તો વર્તમાન મૂલ્યની બાજુમાં ટિક દેખાય છે. પસંદગીઓ તરત જ ટિકિટ અપડેટ કરે છે, ઓડિટ-ટ્રેલ એન્ટ્રી લખે છે, ફોલ્ડર ગણતરીઓ રિફ્રેશ કરે છે, અને લાગુ પડે તો રીડિંગ પેનનું Status ડ્રોપડાઉન સિંક કરે છે.',
            'rightclick_priority' => '<strong>Set priority &rarr;</strong> &mdash; એ જ ફ્લાયઆઉટ પેટર્ન, દરેકના રંગને સ્વોચ તરીકે લઈને સક્રિય પ્રાથમિકતાઓની લુકઅપમાંથી લેવામાં આવેલ. પ્રથમ પંક્તિ સોંપણી સાફ કરવા માટે <em>(કોઈ પ્રાથમિકતા નહીં)</em> વિકલ્પ છે (પ્રાથમિકતા nullable છે).',
            'rightclick_assign' => '<strong>Assign to &rarr;</strong> &mdash; ગ્રે ઇનિશિયલ ચિપ સાથે દરેક લોડ થયેલ વિશ્લેષકને યાદીબદ્ધ કરતું સબમેનૂ, ઉપરાંત સાફ કરવા માટે ટોચે <em>(અસોંપાયેલ)</em> પંક્તિ. પસંદગીઓ <code>assigned_analyst_id</code> અને <code>owner_id</code> બંને સેટ કરે છે જેથી રીડિંગ પેનનું Owner ફીલ્ડ સિંકમાં રહે.',
            'rightclick_cmdb' => '<strong>Link CMDB object&hellip;</strong> &mdash; સર્ચ-એઝ-યુ-ટાઈપ પિકર ખોલે છે. લિંક કરવા માટે પરિણામ પર ક્લિક કરો, પછી પસંદ કરવાનું ચાલુ રાખો &mdash; ઇનપુટ સાફ થાય છે અને આગલા માટે ફરીથી ફોકસ થાય છે, અને મોડલની અંદર "Recently linked" લોગ તમારા ગ્રીન-ટિક કન્ફર્મેશનની ચાલુ યાદી બતાવે છે.',
            'rightclick_time' => '<strong>Record time&hellip;</strong> &mdash; મિનિટ + ડેટટાઈમ પિકર (ડિફોલ્ટ "now" જેથી તમે બેકડેટ પણ કરી શકો) + વૈકલ્પિક નોંધ બોક્સ સાથે મોડલ ખોલે છે.',
            'rightclick_tip' => 'જો તમે કૉન્ટેક્સ્ટ મેનૂ દ્વારા જેના પર કાર્યવાહી કરી રહ્યા છો તે ટિકિટ રીડિંગ પેનમાં ખુલેલી હોય તે જ હોય, તો ત્યાંનો સંબંધિત વિભાગ (Status / Priority ડ્રોપડાઉન, CMDB ઑબ્જેક્ટ, ટાઈમ એન્ટ્રીઝ) મોડલ બંધ થાય ત્યારે આપમેળે રિફ્રેશ થાય છે જેથી UI સિંકમાં રહે.',
            'time_heading' => '<strong>સમય રેકોર્ડ કરવો</strong>',
            'time_body' => 'ટિકિટ પર વિતાવેલો સમય રીડિંગ પેનમાં એક સમર્પિત <strong>Time Entries</strong> વિભાગમાં લોગ થાય છે, જે લિંક કરેલ CMDB ઑબ્જેક્ટ્સ પેનલ અને Notes પેનલ વચ્ચે બેસે છે. હેડર ચાલુ કુલ સરવાળો બતાવે છે (દા.ત. "Total 2h 30m"), અને નીચેની દરેક એન્ટ્રી વિતાવેલો સમય, વિશ્લેષક, તારીખ, અને તમે ઉમેરેલી કોઈપણ નોંધ બતાવે છે.',
            'time_step1' => '<strong>ઇનલાઇન ફોર્મ</strong> &mdash; ન્યુમેરિક ઇનપુટમાં વિતાવેલી મિનિટો ટાઈપ કરો, નોંધ ઇનપુટમાં વૈકલ્પિક ટૂંકું વર્ણન, અને <strong>ઉમેરો</strong> પર ક્લિક કરો. નવી એન્ટ્રી તમારા નામ અને વર્તમાન ટાઈમસ્ટેમ્પ સાથે તરત જ યાદીની ટોચે દેખાય છે.',
            'time_step2' => '<strong>રાઇટ-ક્લિક દ્વારા બેકડેટ</strong> &mdash; જો તમારે અગાઉ રેકોર્ડ કરવાનું ભૂલી ગયેલો સમય લોગ કરવાની જરૂર હોય, તો યાદીમાં ટિકિટ પર રાઇટ-ક્લિક કરો અને <strong>Record time&hellip;</strong> પસંદ કરો. મોડલમાં ડેટટાઈમ પિકર શામેલ છે જેથી તમે એન્ટ્રીને કામ થયું તે વાસ્તવિક સમય સાથે સ્ટેમ્પ કરી શકો.',
            'time_step3' => '<strong>તમારી પોતાની એન્ટ્રીઝ કાઢી નાખો</strong> &mdash; તમે લોગ કરેલી એન્ટ્રીઝની બાજુમાં નાનું &times; બટન દેખાય છે. સોફ્ટ-ડિલીટ કરવા માટે તેના પર ક્લિક કરો (અને પુષ્ટિ કરો) &mdash; પંક્તિ ઓડિટ માટે <code>is_active = 0</code> સાથે ડેટાબેઝમાં રહે છે, પણ યાદીમાંથી અદૃશ્ય થાય છે. તમે બીજા વિશ્લેષકોની એન્ટ્રીઝ કાઢી શકતા નથી.',
            'time_tip1' => 'સમય સાદી મિનિટો તરીકે સંગ્રહાય છે (45 min, 90 min, વગેરે) અને UI માં <code>45m</code> અથવા <code>1h 30m</code> તરીકે દર્શાવાય છે &mdash; ટૂંકા ફિક્સ માટે પૂરતું ઝીણું, દશાંશ-કલાક રાઉન્ડિંગની કોઈ પીડા નહીં.',
            'time_tip2' => 'દરેક ફીલ્ડ ચેન્જ ટિકિટના પ્રવૃત્તિ ટ્રેલમાં રેકોર્ડ થાય છે. તમે હંમેશા જોઈ શકો છો કે કોણે શું અને ક્યારે બદલ્યું, જે ઓડિટ કમ્પ્લાયન્સ અને વિશ્લેષકો વચ્ચેના હેન્ડઓવર માટે જરૂરી છે.',
        ],
        'comments' => [
            'heading' => 'ટિપ્પણીઓ &amp; જોડાણો',
            'intro' => 'પ્રવૃત્તિ ટ્રેલ દરેક ટિકિટનું હૃદય છે. તે લેવાયેલી દરેક ક્રિયા &mdash; ટિપ્પણીઓ, ફીલ્ડ ચેન્જ, મોકલાયેલા ઈમેલ, અને જોડેલી ફાઇલો &mdash; ને એક ક્રમાનુસાર ટાઈમલાઈનમાં કેપ્ચર કરે છે જે સપોર્ટ વિનંતીની સંપૂર્ણ કહાની કહે છે.',
            'adding_heading' => '<strong>ટિપ્પણીઓ ઉમેરવી</strong>',
            'step1' => '<strong>ટિકિટ ખોલો</strong> &mdash; તેની રીડિંગ પેન લોડ કરવા માટે ઇનબોક્સમાંની કોઈપણ ટિકિટ પર ક્લિક કરો. સંપૂર્ણ પ્રવૃત્તિ ટ્રેલ અને નીચે ટિપ્પણી બોક્સ જોવા માટે નીચે સ્ક્રોલ કરો.',
            'step2' => '<strong>તમારી નોંધ લખો</strong> &mdash; ટિપ્પણી એડિટર ખોલવા માટે Add Note બટનનો ઉપયોગ કરો. નોંધો ડિફોલ્ટ રીતે આંતરિક હોય છે, ફક્ત સર્વિસ ડેસ્કના વિશ્લેષકોને જ દેખાય છે.',
            'step3' => '<strong>ઈમેલ દ્વારા જવાબ આપો અથવા ફોરવર્ડ કરો</strong> &mdash; એન્ડ યુઝર અથવા થર્ડ પાર્ટીને સંદેશ મોકલવા માટે Reply અથવા Forward ક્રિયાઓનો ઉપયોગ કરો. ઈમેલ આઉટબાઉન્ડ સંદેશ સામગ્રી સાથે પ્રવૃત્તિ ટ્રેલમાં લોગ થાય છે.',
            'files_heading' => '<strong>ફાઇલ જોડાણો</strong>',
            'files_body' => 'સ્ક્રીનશોટ, લોગ, દસ્તાવેજો, અથવા કોઈપણ સપોર્ટિંગ ફાઇલ સીધી ટિકિટ સાથે જોડો. ફાઇલોને એટેચમેન્ટ ડ્રોપ ઝોનમાં ડ્રેગ કરી શકાય છે અથવા ફાઇલ બ્રાઉઝર વડે પસંદ કરી શકાય છે. જોડાણો સર્વર પર સંગ્રહાય છે અને ટિકિટના પ્રવૃત્તિ ટ્રેલ સાથે લિંક થાય છે જેથી કંઈ ખોવાય નહીં.',
            'audit_heading' => '<strong>ઓડિટ લોગિંગ</strong>',
            'audit_body' => 'પ્રવૃત્તિ ટ્રેલ વિશ્લેષકના હસ્તક્ષેપ વિના આપમેળે દરેક ક્રિયા રેકોર્ડ કરે છે. જ્યારે પ્રાથમિકતા Medium થી High માં બદલાય છે, ત્યારે જૂનું અને નવું મૂલ્ય કેપ્ચર થાય છે. જ્યારે ટિકિટ ફરીથી સોંપાય છે, ત્યારે અગાઉના અને નવા બંને વિશ્લેષક લોગ થાય છે. આ એક સંપૂર્ણ, ટેમ્પર-પ્રૂફ ઇતિહાસ બનાવે છે જે ITIL ઓડિટ જરૂરિયાતોને પૂર્ણ કરે છે અને મેનેજર્સને ટિકિટોનું સંચાલન કેવી રીતે થઈ રહ્યું છે તે સમજવામાં મદદ કરે છે.',
            'tip' => 'ઈમેલ દ્વારા જવાબ આપતી વખતે, તમે એ જ ક્રિયામાં Cc પ્રાપ્તકર્તાઓ ઉમેરી શકો છો અને ફાઇલો જોડી શકો છો. સમગ્ર ઈમેલ વાતચીત ટિકિટના પ્રવૃત્તિ ટ્રેલમાં થ્રેડ થાય છે, જે બધા સંવાદને એક જ જગ્યાએ રાખે છે.',
        ],
        'ai' => [
            'heading' => 'AI ટૂલ્સ',
            'intro' => 'ટિકિટ વર્કફ્લોની અંદર બે Claude-સંચાલિત ફીચર્સ છે: <strong>Reply Cleanup</strong> એક કાચા ડ્રાફ્ટને યોગ્ય રીતે ફોર્મેટ કરેલ ઈમેલમાં ફરીથી લખે છે, અને <strong>Ask AI</strong> ટિકિટ કૉન્ટેક્સ્ટનો ઉપયોગ કરીને નેચરલ લેંગ્વેજમાં નોલેજ બેઝ શોધે છે.',
            'cleanup_heading' => '<strong>Reply Cleanup &mdash; ✨ button in the reply editor</strong>',
            'cleanup_body' => 'જવાબમાં ઝડપી કાચો ડ્રાફ્ટ ટાઈપ કરો (અથવા ફક્ત બુલેટ પોઈન્ટ્સ જેમ કે *"need to restart the print service, take screenshot for them"*) અને <strong>✨ Cleanup</strong> બટન પર ક્લિક કરો. Claude તેને યોગ્ય રીતે ફોર્મેટ કરેલ ઈમેલ તરીકે ફરીથી લખે છે &mdash; વિનંતી કરનાર તરફથી <em>Dear [name],</em> ગ્રીટિંગ ઉમેરે છે, વ્યાકરણ સુધારે છે, ગોઠવેલ ટોન લાગુ કરે છે, અને <em>Kind regards,</em> સાથે સહી કરે છે. પ્રોમ્પ્ટ એ રીતે લૉક કરેલ છે કે તે ટેકનિકલ વિગતો બનાવટ કરશે નહીં, માફી ઘડી કાઢશે નહીં, અથવા તમે લખ્યું છે તેનાથી વધુ સામગ્રી ભરશે નહીં.',
            'cleanup_streams' => '<strong>લાઈવ સ્ટ્રીમ</strong> &mdash; Claude તેને જનરેટ કરે તેમ ફરીથી લખેલું ટેક્સ્ટ એડિટરમાં દેખાય છે (સ્પિનર સામે રાહ જોવાની જરૂર નથી).',
            'cleanup_undo' => '<strong>30 સેકન્ડ માટે Undo લિંક</strong> &mdash; જો Claude ફરીથી લખવામાં ગડબડ કરે, તો ફરીથી લખવાનું પૂર્ણ થયા પછી 30 સેકન્ડ માટે એડિટરની નીચે એક નાની <em>Undo</em> લિંક દેખાય છે, જે મૂળ ડ્રાફ્ટ પુનઃસ્થાપિત કરે છે.',
            'cleanup_tone' => '<strong>ટોન પ્રમાણે</strong> &mdash; <strong>Settings &rarr; Reply Cleanup</strong> હેઠળ ગોઠવી શકાય તેવા ત્રણ ટોન પ્રીસેટ: <em>Friendly</em> (ડિફોલ્ટ), <em>Formal</em>, <em>Brief</em>. તમારી ટીમની હાઉસ સ્ટાઈલ સાથે મેળ ખાય તે પસંદ કરો.',
            'cleanup_key' => '<strong>પોતાની API કી</strong> &mdash; RFP / Knowledge / Workflow AI ફીચર્સથી અલગ Anthropic કી જેથી તેનો ઉપયોગ Anthropic બિલિંગ ડેશબોર્ડ પર પોતાની અલગ લાઈન તરીકે દેખાય. <strong>Settings &rarr; Reply Cleanup</strong> હેઠળ ગોઠવેલ.',
            'cleanup_tip' => 'Cleanup નો શ્રેષ્ઠ ઉપયોગ રૂટિન "મેં આ પ્રયત્ન કર્યો, કૃપા કરીને X પ્રયત્ન કરો" સ્ટાઈલના જવાબો માટે થાય છે. લાંબા, સૂક્ષ્મ સંદેશાઓ માટે તમે તેમને જાતે લખવા માંગશો &mdash; AI સ્ટ્રક્ચરમાં શ્રેષ્ઠ છે પણ તમારા ચોક્કસ વાતાવરણને જાણતું નથી.',
            'ask_heading' => '<strong>Ask AI &mdash; ટિકિટ ટૂલબારમાં 🤖 બટન</strong>',
            'ask_body' => 'ખુલેલી ટિકિટના વિષય, બોડી અને રીડિંગ-પેન કૉન્ટેક્સ્ટને જાણતી સ્લાઈડ-ઇન ચેટ પેનલ ખોલવા માટે ટિકિટ ટૂલબારમાં <strong>Ask AI</strong> બટન (🤖) પર ક્લિક કરો. તેને *"have we seen this before?"* અથવા *"what\'s the usual fix for this error?"* જેવા પ્રશ્નો પૂછો અને તે <a href="../knowledge/" style="color:#0078d4;">Knowledge</a> બેઝને સિમેન્ટિકલી (Claude + OpenAI એમ્બેડિંગ્સ મારફતે) શોધે છે અને સંબંધિત આર્ટિકલ્સ સાથે જવાબ આપે છે, જેમાં તેમને ખોલવા માટે ડાયરેક્ટ લિંક હોય છે.',
            'ask_context' => '<strong>કૉન્ટેક્સ્ટ-અવેર</strong> &mdash; પેનલ જાણે છે કે તમે કઈ ટિકિટ જોઈ રહ્યા છો, જેથી તમે સામાન્ય પ્રશ્નો પૂછી શકો અને તે સંબંધિત કૉન્ટેક્સ્ટ શોધી કાઢે છે.',
            'ask_linked' => '<strong>લિંક કરેલા આર્ટિકલ્સ</strong> &mdash; સૂચનો ક્લિક કરી શકાય તેવા છે અને મેચ થતા નોલેજ આર્ટિકલને નવા ટેબમાં ખોલે છે.',
            'ask_shared' => '<strong>Knowledge મોડ્યુલ સાથે શેર કરેલ</strong> &mdash; AI એ જ કી + મોડેલનો ઉપયોગ કરે છે જે Knowledge AI શોધ કરે છે, જેથી એકવાર ગોઠવવાથી તમને બંને મળે છે. સેટઅપ વિગતો માટે Knowledge મોડ્યુલની મદદ જુઓ.',
        ],
        'csat' => [
            'heading' => 'ગ્રાહક સંતોષ સર્વે (CSAT)',
            'intro' => 'ટિકિટ ઉકેલાય ત્યારે વિનંતી કરનારને 1&ndash;5 સંતોષ સર્વે ઈમેલ કરો, નો-લોગિન લેન્ડિંગ પેજ પર જવાબ કેપ્ચર કરો, અને એક સમર્પિત એનાલિટિક્સ પેજ પર પ્રતિ-વિશ્લેષક ટ્રેન્ડ ટ્રૅક કરો.',
            'modes_heading' => '<strong>બે ટ્રિગર મોડ &mdash; એક પસંદ કરો</strong>',
            'mode_auto' => '<strong>બંધ થતા આપમેળે</strong> &mdash; જ્યારે ટિકિટ કોઈપણ બંધ સ્થિતિમાં જાય છે ત્યારે સર્વે આપમેળે ક્યૂ થાય છે. વિશ્લેષકે કંઈ કરવાની જરૂર નથી &mdash; ઉકેલ સર્વે ચલાવે છે.',
            'mode_manual' => '<strong>ફક્ત મેન્યુઅલ</strong> &mdash; જ્યારે વિશ્લેષક પૂછવા માંગે ત્યારે ટિકિટ ટૂલબારમાં ⭐ <strong>Feedback</strong> બટન પર ક્લિક કરે છે. જ્યારે તમે દરેક ટિકિટ પ્રમાણે ફીડબેક માંગવો કે નહીં તે નક્કી કરવાનું પસંદ કરો ત્યારે ઉપયોગી.',
            'mode_off' => '<strong>બંધ</strong> &mdash; ફીચર નિષ્ક્રિય; કોઈ સર્વે ઈમેલ મોકલવામાં આવતા નથી.',
            'modes_choose' => '<strong>Tickets &rarr; Settings &rarr; CSAT</strong> હેઠળ પસંદ કરો. મેન્યુઅલ બટન <em>auto</em> મોડમાં પણ કામ કરે છે &mdash; જરૂર પડે તો વિશ્લેષકો પહેલેથી સર્વે થયેલી ટિકિટ પર ફરીથી ફીડબેક માંગી શકે છે.',
            'template_heading' => '<strong>ઈમેલ ટેમ્પલેટ</strong>',
            'template_body' => 'સર્વે ઈમેલની સામગ્રી હાલના <strong>Email templates</strong> ટેબમાંથી આવે છે &mdash; ઇવેન્ટ <strong>CSAT survey</strong> (<em>Ticket assigned</em> / <em>Ticket closed</em> ની સાથે નવો ઇવેન્ટ) સાથે ટેમ્પલેટ બનાવો અને જ્યાં તમે રેટિંગ URL દેખાવા માંગો ત્યાં <code>[csat_link]</code> મર્જ કોડ એમ્બેડ કરો. સ્ટાન્ડર્ડ મર્જ કોડ (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) સામાન્ય રીતે ઉપલબ્ધ છે.',
            'template_tip' => 'જો કોઈ સક્રિય CSAT ટેમ્પલેટ અસ્તિત્વમાં ન હોય, તો <em>Feedback</em> બટન સ્પષ્ટ ભૂલ સાથે ઇનકાર કરે છે અને ઓટો-ટ્રિગર ચૂપચાપ છોડી દે છે &mdash; તમે ક્યારેય ડેડ સર્વે લિંક ઉત્પન્ન કરી શકતા નથી.',
            'survey_heading' => '<strong>સર્વે પેજ</strong>',
            'survey_body' => 'વિનંતી કરનાર ઈમેલમાંની લિંક પર ક્લિક કરે છે અને 1&ndash;5 પિકર વત્તા વૈકલ્પિક ટિપ્પણી બોક્સ સાથે નો-લોગિન પેજ પર પહોંચે છે. <strong>Settings &rarr; CSAT</strong> હેઠળ ગોઠવી શકાય તેવી બે વિઝ્યુઅલ સ્ટાઈલ:',
            'survey_stars' => '<strong>તારા</strong> &mdash; ક્લાસિક ફિલ-ઓન-હોવર ટ્રેલિંગ વર્તન. તારો #3 હોવર કરવાથી #1+#2+#3 ગોલ્ડમાં ભરાય છે. લોક કરવા માટે ક્લિક કરો.',
            'survey_emojis' => '<strong>ઈમોજી</strong> &mdash; 5 ચહેરા 😡 🙁 😐 🙂 😀 40% ઓપેસિટી પર ગ્રેસ્કેલથી શરૂ થાય છે; હોવર કરેલ અથવા પસંદ કરેલ ચહેરો 1.25&times; સ્કેલ પર પૂરા રંગમાં પાછો આવે છે. લોક કરવા માટે ક્લિક કરો.',
            'survey_store' => 'બંને મોડ એ જ 1&ndash;5 નંબર સંગ્રહે છે જેથી કઈ સ્ટાઈલ વપરાય છે તેને ધ્યાનમાં લીધા વિના ડેશબોર્ડ અને એવરેજ એકસરખા કામ કરે. સર્વે URL વન-શોટ છે &mdash; એકવાર યુઝર સબમિટ કરે, પછી એ જ લિંક ફરીથી સબમિશનનો ઇનકાર કરે છે.',
            'analytics_heading' => '<strong>એનાલિટિક્સ પેજ</strong>',
            'analytics_body' => '<code>tickets/csat/</code> પર એનાલિટિક્સ ડેશબોર્ડ ખોલવા માટે ⭐ <strong>CSAT</strong> નેવ બટન (Rota અને Settings વચ્ચે) પર ક્લિક કરો. વિન્ડો પસંદ કરી શકાય તેવી: 7 / 30 / 90 / 365 દિવસ.',
            'card_kpi_title' => 'KPI ટાઇલ્સ',
            'card_kpi_body' => 'સરેરાશ રેટિંગ (5 માંથી), જવાબ ગણતરી, જવાબ દર (જવાબ આપ્યા ÷ મોકલ્યા)',
            'card_dist_title' => 'સ્કોર વિતરણ',
            'card_dist_body' => 'ચોક્કસ ગણતરીઓ અને ટકાવારી બતાવતો 1–5 રેટિંગનો બાર ચાર્ટ',
            'card_leader_title' => 'પ્રતિ-વિશ્લેષક લીડરબોર્ડ',
            'card_leader_body' => 'પ્રતિ વિશ્લેષક સરેરાશ રેટિંગ + જવાબ ગણતરી, સરેરાશ પ્રમાણે ઉતરતા ક્રમમાં. ડેવલપમેન્ટ વાતચીતો માટે ઉપયોગ કરો',
            'card_recent_title' => 'તાજેતરના જવાબો',
            'card_recent_body' => 'તેમની ફ્રી-ટેક્સ્ટ ટિપ્પણીઓ સાથે 25 સૌથી તાજેતરના રેટિંગ, સ્રોત ટિકિટ સાથે પાછા લિંક કરેલ',
            'analytics_tip' => 'પ્રતિ-વિશ્લેષક એટ્રિબ્યુશન ટિકિટ પુનઃસોંપણી પછી પણ ટકી રહે છે કારણ કે વિશ્લેષક id મોકલવાના સમયે સર્વે પંક્તિ પર કેપ્ચર થાય છે, લાઈવ લુકઅપ થતું નથી. જો ટિકિટ બંધ થતા પહેલા આમતેમ ફરે, તો જે વિશ્લેષકે ખરેખર તેને બંધ કરી તે રેટિંગનો માલિક બને છે.',
            'one_heading' => '<strong>પ્રતિ ટિકિટ એક સર્વે</strong>',
            'one_body' => 'જો <em>One survey per ticket</em> ચાલુ હોય (ડિફોલ્ટ), તો ફરીથી ખોલેલી-પછી-બંધ થયેલી ટિકિટને બીજો સર્વે ત્યારે જ મળે છે જ્યારે વિશ્લેષક તેને મેન્યુઅલી ટ્રિગર કરે &mdash; આ સતત ચક્રમાં ફરતી અસ્થિર ટિકિટને સર્વે-સ્પેમ કરતી અટકાવે છે. જો તમે દરેક બંધ થવા પર નવો સર્વે ફાયર થાય તેમ ઈચ્છતા હો તો તેને બંધ કરો.',
        ],
        'users' => [
            'heading' => 'વપરાશકર્તા વ્યવસ્થાપન',
            'intro' => '<strong>Users</strong> નેવ બટન <code>tickets/users.php</code> ખોલે છે &mdash; દરેક એન્ડ યુઝર (ટિકિટ ઉઠાવનારા લોકો, વિશ્લેષકો નહીં) ની ડિરેક્ટરી, દરેકના ટિકિટ ઇતિહાસ સાથે.',
            'p_intro' => 'યુઝર્સ સિસ્ટમમાં ચાર રિએક્ટિવ રીતે આવે છે &mdash; પોર્ટલ સેલ્ફ-રજિસ્ટ્રેશન, નવા મોકલનાર તરફથી ઈનબાઉન્ડ ઈમેલ, મેઈલબોક્સ પોલર, અથવા ટ્રિગર થયેલી ટિકિટમાંથી વર્કફ્લો એન્જિન એક બનાવે છે. આ મોટાભાગના કેસને આવરી લે છે, પણ Users પેજ તમને યુઝરને <strong>પ્રી-ક્રિએટ</strong> કરવાની (દા.ત. કોઈ નવો કર્મચારી જેને ટૂંક સમયમાં એક્સેસની જરૂર પડશે) અને હાલની પંક્તિઓને <strong>સંપાદિત</strong> અથવા <strong>કાઢી નાખવાની</strong> પણ મંજૂરી આપે છે.',
            'add_heading' => '<strong>યુઝર ઉમેરો</strong>',
            'add_body' => 'યુઝર્સ-યાદી હેડરમાંનું <strong>Add</strong> બટન એક મોડલ ખોલે છે:',
            'add_email' => '<strong>ઈમેલ</strong> (જરૂરી) &mdash; અનન્ય હોવું જોઈએ, અને વિશ્લેષક એકાઉન્ટ સાથે અથડાવું ન જોઈએ.',
            'add_names' => '<strong>ડિસ્પ્લે નામ / પસંદગીનું નામ</strong> &mdash; વૈકલ્પિક. પસંદગીનું નામ એ છે જેનાથી યુઝર પોતાને ઈમેલમાં ગ્રીટ થતા જુએ છે (દા.ત. <em>"Ed Mozley"</em> ને બદલે <em>"Ed"</em>).',
            'add_password' => '<strong>પાસવર્ડ</strong> &mdash; વૈકલ્પિક. તેને ખાલી છોડવાથી <em>પાસવર્ડ-રહિત</em> એકાઉન્ટ બને છે &mdash; બરાબર એ જ સ્થિતિ જેમાં ઈનબાઉન્ડ-ટિકિટ યુઝર્સ શરૂ થાય છે. યુઝર પછીથી પોતાનો પાસવર્ડ સેટ કરીને સેલ્ફ-સર્વિસ પોર્ટલના રજિસ્ટર ફ્લો મારફતે એકાઉન્ટ ક્લેમ કરી શકે છે.',
            'add_details' => '<strong>હોદ્દો, વિભાગ, ઓફિસ, ફોન, મોબાઇલ, એમ્પ્લોયી ID અને મેનેજર</strong> &mdash; બધા વૈકલ્પિક, અને બધા લોગિનને બદલે <em>વ્યક્તિ</em>નું વર્ણન કરે છે. ભરવા યોગ્ય: <strong>ઓફિસ</strong> તમને કોઈને શોધવા જતા પહેલા જણાવે છે કે તે કઈ સાઈટ પર છે, <strong>મેનેજર</strong> રિપોર્ટિંગ લાઈન રેકોર્ડ કરે છે, અને <strong>એમ્પ્લોયી ID</strong> એ જોઈન કી છે જ્યારે તમે એવી પેરોલ સિસ્ટમ સામે રિકન્સાઈલ કરો છો જેણે ક્યારેય ઈમેલ સરનામા વિશે સાંભળ્યું જ ન હોય. જ્યાં તમે ડિરેક્ટરીમાંથી ઇમ્પોર્ટ કરો છો, ત્યાં આ બધું ભરેલું આવે છે. CardDAV એડ્રેસ બુક એમ્પ્લોયી ID અને મેનેજર સિવાય બધું ભરે છે, જેને કૉન્ટેક્ટ કાર્ડમાં સંગ્રહવા માટે ક્યાંય જગ્યા નથી.',
            'managed_heading' => '<strong>ક્યાંક બીજે જાળવવામાં આવતા લોકો</strong>',
            'source_body' => '<strong>વ્યક્તિ ક્યાંથી આવે છે</strong> તે તેની વિગતોમાં નામાંકિત છે (<em>Details from: Contoso AD - directory</em>), અને સર્ચ બોક્સ હેઠળનું <strong>Source</strong> ફિલ્ટર ફક્ત એક ડિરેક્ટરી અથવા એડ્રેસ બુકના લોકોને, અથવા ફક્ત FreeITSM માં ઉમેરાયેલાઓને, દરેકની બાજુમાં ગણતરી સાથે યાદીબદ્ધ કરે છે. જ્યારે કોઈપણ સ્રોત સાથે લિંક થાય ત્યારે તે દેખાય છે.',
            'add_book_body' => '<strong>એડ્રેસ બુકમાં ઉમેરો.</strong> જેણે ઈમેલ કર્યો હોય તેવી કોઈ વ્યક્તિ અહીં અસ્તિત્વમાં છે પણ કોઈ એડ્રેસ બુકમાં નથી. જો એડમિનિસ્ટ્રેટરે <em>Let analysts add people to this address book</em> (System &rarr; Authentication, એડ્રેસ બુક પર) ચાલુ કર્યું હોય, તો તે વ્યક્તિને Edit ની બાજુમાં <strong>Add to address book</strong> બટન મળે છે. તે પહેલા પૂછે છે, કાર્ડ પર શું જશે તે બતાવીને, પછી તેમનો કૉન્ટેક્ટ બનાવે છે અને તેમને લિંક કરે છે &mdash; એ જ વ્યક્તિ, નકલ નહીં. તે એવી કોઈને ઉમેરશે નહીં જેનું ઈમેલ સરનામું બુકમાં પહેલેથી છે (તેના બદલે ઇમ્પોર્ટ ચલાવો), અને તે ખાતરી કરે છે કે આગલો ઇમ્પોર્ટ નવા કૉન્ટેક્ટને પસંદ કરી લેશે, અથવા તે કાર્ડને પાછું બહાર કાઢે છે.',
            'managed_body' => 'જ્યાં કોઈ વ્યક્તિને ઇમ્પોર્ટ કરવામાં આવી હોય &mdash; LDAP અથવા Active Directory માંથી, અથવા CardDAV એડ્રેસ બુકમાંથી &mdash; ત્યાં તે સ્રોતની માલિકીની વિગતો <strong>રીડ-ઓન્લી</strong> હોય છે અને મોડલ તેમને ગ્રે કરી દે છે. તેઓ જ્યાંથી આવ્યા તે જ સત્યનો સ્રોત છે, અને આગલો ઇમ્પોર્ટ અહીં ટાઈપ કરેલી કોઈપણ વસ્તુને ઓવરરાઈટ કરી દેશે, તેથી સેવને એક કલાક પછી ચૂપચાપ પાછું ફેરવવાને બદલે સીધો જ ઇનકાર કરવામાં આવે છે. <strong>કઈ</strong> વિગતો સ્રોત પર આધાર રાખે છે: ડિરેક્ટરીની માલિકી બધી સાત પર છે, જ્યારે એડ્રેસ બુકની માલિકી પાંચ પર છે &mdash; તેની પાસે એમ્પ્લોયી નંબર અથવા રિપોર્ટિંગ લાઈન રાખવા માટે ક્યાંય જગ્યા નથી, તેથી તે બે તમારે ભરવા માટે જ રહે છે. અને જો એડ્રેસ બુકમાં <em>write changes back</em> ચાલુ હોય, તો તેમાંથી કોઈ લૉક નથી: તમે જે ટાઈપ કરો છો તે કૉન્ટેક્ટ કાર્ડને મોકલવામાં આવે છે, તેથી આગલા ઇમ્પોર્ટ માટે પાછું ફેરવવા જેવું કંઈ રહેતું નથી. રેકોર્ડ પરની બાકીની દરેક વસ્તુ, તેમની કંપની અને પાસવર્ડ સહિત, હંમેશા સંપાદનયોગ્ય છે.',
            'edit_heading' => '<strong>યુઝર સંપાદિત કરો</strong>',
            'edit_body' => 'યાદીમાંથી યુઝર પસંદ કરો, પછી ડિટેલ હેડરમાં <strong>Edit</strong> પર ક્લિક કરો. એ જ મોડલ, પ્રી-ફિલ્ડ. પાસવર્ડ વગર સાચવવાથી હાલનો હેશ યથાવત રહે છે; એક આપવાથી તે રીસેટ થાય છે.',
            'delete_heading' => '<strong>યુઝર કાઢી નાખો</strong>',
            'delete_body' => '<strong>Delete</strong> બટન <strong>FK-safe</strong> છે: જો યુઝર કોઈપણ ટિકિટો પર વિનંતી કરનાર હોય અથવા <code>users_assets</code> માં કોઈ પંક્તિઓ ધરાવતો હોય, તો તે ઇનકાર કરે છે, અને સ્પષ્ટ <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em> સંદેશ પરત આપે છે. ઓડિટ ઇતિહાસ ક્યારેય ચૂપચાપ તૂટી શકતો નથી.',
            'tip' => 'બધા મોડલ ફીલ્ડ્સમાં બ્રાઉઝર ઓટોફિલ નિષ્ક્રિય છે (પાસવર્ડ ફીલ્ડ પર <code>autocomplete="new-password"</code> સહિત) જેથી વિશ્લેષકના પોતાના સાચવેલા ક્રેડેન્શિયલ્સ એવા ફોર્મમાં સૂચવવામાં ન આવે જેનો સંપૂર્ણ હેતુ <em>બીજા કોઈનો</em> રેકોર્ડ બનાવવાનો છે.',
            'groups_heading' => '<strong>Groups</strong>',
            'groups_body' => '<strong>People</strong> ની બાજુમાંનો <strong>Groups</strong> ટેબ લોકોના નામાંકિત જૂથો ધરાવે છે &mdash; વિશ્લેષકો અને સેલ્ફ-સર્વિસ પોર્ટલ યુઝર્સ એક જ જૂથમાં સાથે. જૂથ અહીં એકવાર બનાવવામાં આવે છે અને પછી સમગ્ર FreeITSM માં ઉપયોગમાં લેવાય છે, જેથી તમે એ જ યાદી બે વાર બનાવ્યા વિના તેને નોલેજ ફોલ્ડરની એક્સેસ આપી શકો અથવા તેને ટ્રેનિંગ કોર્સ સોંપી શકો.',
            'groups_make' => 'Groups ટેબ પર <strong>Add</strong> વડે <strong>એક બનાવો</strong>: એક નામ, અને ભરવા યોગ્ય વર્ણન, કારણ કે આગલી વ્યક્તિ જૂથ શેના માટે છે તે કહી શકે તે જરૂરી છે.',
            'groups_add' => 'તેમને શોધીને <strong>લોકો ઉમેરો</strong> &mdash; તે વિશ્લેષકો અને પોર્ટલ યુઝર્સને એકસાથે શોધે છે, જેથી તમારે જાણવાની જરૂર નથી કે કોઈ કયા પ્રકારનો છે.',
            'groups_expiry' => 'જ્યાં એક્સેસ કામચલાઉ હોય ત્યાં <strong>સભ્યપદને સમાપ્તિ તારીખ આપો</strong>. બે અઠવાડિયા માટે સાઈટ પર રહેલા ત્રણ એન્જિનિયર છેલ્લા દિવસ સાથે અંદર જાય છે અને તે પસાર થાય ત્યારે પોતાની મેળે જૂથમાંથી બહાર નીકળી જાય છે. સમાપ્ત થયેલું સભ્યપદ યાદીમાં જ રહે છે, સમાપ્ત તરીકે ચિહ્નિત, જેથી તમે હજુ પણ જોઈ શકો કે કોની પાસે એક્સેસ હતી અને ક્યાં સુધી.',
            'groups_uses' => '<strong>જૂથ શેના માટે સારું છે:</strong> નોલેજ ફોલ્ડરની એક્સેસ આપવા માટે, અને એકસાથે લોકોના સેટને LMS ટ્રેનિંગ સોંપવા માટે. સભ્યપદ ફેરફારો તરત જ અસરકારક બને છે &mdash; પછીથી ફરીથી લાગુ કરવા જેવું કંઈ રહેતું નથી.',
            'groups_admin' => '<strong>Tickets મોડ્યુલ ધરાવતું કોઈપણ જૂથો જોઈ શકે છે; ફક્ત એડમિનિસ્ટ્રેટર જ કોઈ એકને બદલી શકે છે.</strong> કોઈને જૂથમાં ઉમેરવાથી તેમને પ્રતિબંધિત નોલેજ ફોલ્ડરની એક્સેસ પણ મળી શકે છે, તેથી તે એક્સેસની ગ્રાન્ટ છે, ફાઇલિંગનો ટુકડો નહીં.',
        ],
        'dash' => [
            'heading' => 'ડેશબોર્ડ',
            'intro' => 'ટિકિટ ડેશબોર્ડ કસ્ટમાઇઝ કરી શકાય તેવા Chart.js વિજેટ્સ સાથે એક નજરમાં એનાલિટિક્સ પૂરું પાડે છે. દરેક વિશ્લેષકનું પોતાનું ડેશબોર્ડ લેઆઉટ હોય છે, જેથી તમે તમારી ભૂમિકા માટે મહત્વના મેટ્રિક્સ પર ધ્યાન કેન્દ્રિત કરી શકો &mdash; ભલે તે વ્યક્તિગત વર્કલોડ હોય, ટીમ થ્રુપુટ હોય, અથવા SLA કમ્પ્લાયન્સ હોય.',
            'step1' => '<strong>Library ખોલો</strong> &mdash; એડિટિંગ મોડમાં જવા માટે Edit Dashboard પર ક્લિક કરો, પછી વિજેટ લાઇબ્રેરી બ્રાઉઝ કરો. પ્રી-બિલ્ટ વિજેટ્સમાંથી પસંદ કરો અથવા ચાર્ટ પ્રકાર અને એગ્રિગેટ કરવાની ડેટા પ્રોપર્ટી પસંદ કરીને પોતાનું બનાવો.',
            'step2' => '<strong>વિજેટ્સ ઉમેરો</strong> &mdash; તેને તમારા ડેશબોર્ડમાં ઉમેરવા માટે લાઇબ્રેરીમાંના કોઈપણ વિજેટ પર + બટન પર ક્લિક કરો. તે તરત જ દેખાય છે અને તમારા ટિકિટ ડેટાબેઝમાંથી લાઈવ ડેટા બતાવવાનું શરૂ કરે છે.',
            'step3' => '<strong>ગોઠવો</strong> &mdash; તેનું ટાઇટલ, ચાર્ટ પ્રકાર (bar, pie, doughnut, line, stacked bar, multi-line), ડેટ રેન્જ ફિલ્ટર, વિભાગ ફિલ્ટર, અને સમય જૂથબદ્ધ (daily, weekly, monthly) કસ્ટમાઇઝ કરવા માટે કોઈપણ વિજેટ પર કોગ આઇકોન પર ક્લિક કરો.',
            'step4' => '<strong>ગોઠવણી કરો</strong> &mdash; વિજેટ્સને ફરીથી ક્રમમાં ગોઠવવા માટે ડ્રેગ અને ડ્રોપ કરો. તમારો લેઆઉટ પ્રતિ-વિશ્લેષક સાચવવામાં આવે છે જેથી તે સેશન્સ દરમિયાન ટકી રહે.',
            'examples' => 'સામાન્ય વિજેટ ઉદાહરણોમાં શામેલ છે: <strong>Tickets by Status</strong> (open vs resolved vs closed બતાવતો ડોનટ ચાર્ટ), <strong>Tickets by Priority</strong> (સિવિયારિટી પ્રમાણે વોલ્યુમનો બાર ચાર્ટ), <strong>Weekly Volume</strong> (સમય જતાં નવી ટિકિટોને ટ્રૅક કરતો લાઈન ચાર્ટ), અને <strong>Analyst Workload</strong> (દરેક વિશ્લેષકની સક્રિય ટિકિટો બતાવતો સ્ટેક્ડ બાર).',
            'tip' => 'વર્તમાન પરફોર્મન્સને પાછલા સમયગાળા સામે સરખાવવા માટે વ્યક્તિગત વિજેટ્સ પર ડેટ રેન્જ ફિલ્ટરનો ઉપયોગ કરો. ઉદાહરણ તરીકે, "This Month vs Last Month" વ્યૂ તમને ટિકિટ વોલ્યુમમાં ટ્રેન્ડ વહેલા શોધવામાં મદદ કરે છે.',
        ],
        'cal_rota' => [
            'heading' => 'કૅલેન્ડર &amp; રોટા',
            'intro' => 'તમારી ટીમને વ્યવસ્થિત રાખવા માટે બે શેડ્યુલિંગ ટૂલ્સ મદદ કરે છે: એક ટિકિટ કૅલેન્ડર જે સમય જતાં વર્કલોડ દર્શાવે છે, અને એક સ્ટાફ રોટા જે શિફ્ટ અને ઓન કોલ ઉપલબ્ધતાનું સંચાલન કરે છે.',
            'cal_heading' => '<strong>કૅલેન્ડર દૃશ્ય</strong>',
            'cal_body' => 'કૅલેન્ડર તમે શેડ્યુલ કરેલી દરેક ટિકિટને દર્શાવે છે &mdash; <strong>Schedule work</strong> વડે, જે ટિકિટ પર જ અને ઇનબોક્સના રાઇટ-ક્લિક મેનૂ પર ઉપલબ્ધ છે &mdash; તેના શેડ્યુલ કરેલા સમયે એક રંગીન બ્લોક તરીકે, જે નિશ્ચિત કલાકને બદલે તેની <strong>વાસ્તવિક લંબાઈ</strong> પ્રમાણે દોરવામાં આવે છે. લાલ બ્લોક <em>High</em> પ્રાથમિકતા દર્શાવે છે, લીલા <em>Low</em> દર્શાવે છે, અને બાકીના બધા માટે વાદળી. નેવિગેટ કરવા માટે <em>Today</em>, <em>&lt;</em> / <em>&gt;</em> શેવરોન, અને <strong>Month / Week / Day</strong> ટૉગલનો ઉપયોગ કરો.',
            'cal_scope' => '<strong>મારું અથવા બધા.</strong> કૅલેન્ડર તમારા પોતાના શેડ્યુલ કરેલા કામ સાથે ખૂલે છે, દૃશ્ય બટનોની બાજુમાં એક <strong>બધા</strong> સ્વિચ સાથે; તમારી પસંદગી યાદ રખાય છે. બધા મોડમાં દરેક ટિકિટ <strong>તેના માલિક પ્રમાણેનો રંગ</strong> ધરાવે છે, જેમાં સ્ક્રીન પર ખરેખર દેખાતા લોકોના નામવાળી લિજેન્ડ હોય છે, અને ટિકિટ પર હોવર કરવાથી બીજે જોયા વગર જ ખબર પડે છે કે તે કોની છે. કોઈનાથી કંઈ છુપાવવામાં આવતું નથી &mdash; આ એ જ ટિકિટો છે જે ઇનબોક્સ પહેલેથી યાદીમાં બતાવે છે.',
            'cal_edit' => '<strong>કામ ફરીથી ગોઠવવું.</strong> <strong>ટિકિટને ડ્રેગ કરો</strong> બીજા દિવસ કે સમય પર: Month દૃશ્યમાં તેનો સમય એ જ રહે છે, અને Week અને Day દૃશ્યમાં તે તમે જ્યાં ડ્રોપ કરો ત્યાંનો સમય લે છે, જે નજીકના પા કલાકે સ્નેપ થાય છે. તેની લંબાઈ ક્યારેય બદલાતી નથી &mdash; ડ્રેગ કરવાનો અર્થ છે <em>તેને ત્યારે શરૂ કરો</em>, <em>તેને લાંબી બનાવો</em> નહીં. અથવા ટિકિટ ખોલવા માટે <strong>ટિકિટ પર ક્લિક કરો</strong>, જ્યાં તમે તારીખ, સમય, અવધિ અને ઓલ-ડે સેટિંગ બદલી શકો છો, અથવા શેડ્યુલ સંપૂર્ણપણે સાફ કરી શકો છો. કૅલેન્ડર <strong>દર થોડીક સેકન્ડે જાતે રિફ્રેશ</strong> પણ થાય છે, જેથી કોઈ સાથી કર્મચારી કંઈક શેડ્યુલ કરે તો તમારે રિલોડ કર્યા વગર જ તે દેખાય &mdash; અને જ્યારે તમારી પાસે ટિકિટ ખુલ્લી હોય અથવા તમે ડ્રેગ કરી રહ્યા હો ત્યારે તે અટકી જાય છે.',
            'cal_month' => '<strong>Month દૃશ્ય</strong> &mdash; ક્લાસિક 6-પંક્તિની ગ્રિડ જેમાં અઠવાડિયાના દિવસોની હેડર સ્ટ્રીપ છે; દરેક દિવસના સેલમાં તેમના શરૂઆતના સમય સાથે વધુમાં વધુ ત્રણ ટિકિટ પિલ દેખાય છે, ઉપરાંત એક <em>+N more</em> લિંક જે તમને તે તારીખના Day દૃશ્યમાં લઈ જાય છે. આજનો દિવસ હાઇલાઇટ થયેલો છે.',
            'cal_week' => '<strong>Week દૃશ્ય</strong> &mdash; ઉપર 24-કલાકની ઊભી ટાઇમલાઇન પર Mon&ndash;Sun. ટિકિટો તેમની શેડ્યુલ કરેલી લંબાઈ પ્રમાણે દેખાય છે, જેથી 15-મિનિટનું કામ અને બપોરનું રિબિલ્ડ અલગ દેખાય. ઓલ-ડે ટિકિટ આખો કૉલમ રોક્યા વગર તેના દિવસની ટોચે એક પાતળી પટ્ટી તરીકે બેસે છે. આજના દિવસનો કૉલમ હાઇલાઇટ થયેલો છે; કલાકની ગ્રિડ સ્ક્રોલ થાય ત્યારે પણ અઠવાડિયાના દિવસોની હેડર સ્થિર રહે છે.',
            'cal_day' => '<strong>Day દૃશ્ય</strong> &mdash; પસંદ કરેલા દિવસ માટે એ જ 24-કલાકની ટાઇમલાઇન સાથેનો એક જ ઊંચો કૉલમ. ટિકિટો <code>ticket_number &mdash; subject</code> અને શરૂઆતનો સમય દર્શાવતા મોટા બ્લોક તરીકે દેખાય છે; તેની વિગતો ખોલવા અથવા તે ક્યારે થાય તે બદલવા માટે એક પર ક્લિક કરો.',
            'rota_heading' => '<strong>સ્ટાફ રોટા</strong>',
            'rota_body' => 'રોટા પેજ ટીમ લીડ્સ અને મેનેજરોને અઠવાડિયા દરમિયાન વિશ્લેષકોની શિફ્ટ શેડ્યુલ કરવા દે છે. પ્રમાણભૂત કામના કલાકો નક્કી કરો, ઓન કોલ ગાળાઓ સોંપો, અને રજાઓ કે ગેરહાજરી ચિહ્નિત કરો જેથી ટીમને હંમેશા ખબર રહે કે કોણ ઉપલબ્ધ છે.',
            'rota_step1' => '<strong>રોટા ગ્રિડ જુઓ</strong> &mdash; રોટા એક ધરી પર વિશ્લેષકો અને બીજી ધરી પર દિવસો દર્શાવે છે, જેમાં શિફ્ટ બ્લોક એક નજરમાં કવરેજ બતાવે છે.',
            'rota_step2' => '<strong>શિફ્ટ ઉમેરો અથવા સંપાદિત કરો</strong> &mdash; શિફ્ટ પ્રકાર સોંપવા માટે એક સેલ પર ક્લિક કરો (દા.ત. Early, Late, Night, On-Call). ફેરફારો તરત જ સચવાય છે.',
            'rota_step3' => '<strong>અગાઉથી આયોજન કરો</strong> &mdash; રોટા અગાઉથી બનાવવા માટે અઠવાડિયા પ્રમાણે આગળ નેવિગેટ કરો. આનાથી જાણીતા વ્યસ્ત ગાળાઓ, રજાઓ કે તાલીમના દિવસો દરમિયાન પૂરતી કવરેજ સુનિશ્ચિત થાય છે.',
            'rota_step4' => '<strong>એકસાથે અનેક સેલ ભરો</strong> &mdash; સેલમાંની શિફ્ટ ઉપાડવા માટે તેના પર <strong>રાઇટ-ક્લિક</strong> કરો અને <em>Copy</em> પસંદ કરો, પછી બીજા પર રાઇટ-ક્લિક કરો અને <em>Paste</em> કરો. એક કરતાં વધુ સેલ માટે, તેમના <strong>બ્લોક પર ડ્રેગ કરો</strong> (અથવા સેલને એક પછી એક ctrl-ક્લિક કરો) અને આખા સેટમાં પેસ્ટ કરો. <strong>દિવસના હેડિંગ</strong> પર હોવર કરવાથી આખો દિવસ પ્રકાશિત થાય છે, અને <strong>વિશ્લેષકના નામ</strong> પર હોવર કરવાથી તેમનું આખું અઠવાડિયું પ્રકાશિત થાય છે &mdash; બેમાંથી કોઈ પર રાઇટ-ક્લિક કરો અને આખામાં પેસ્ટ કરો. જ્યાં કેટલાક સેલમાં પહેલેથી શિફ્ટ હોય ત્યાં મેનૂ સાદા શબ્દોમાં બંને રીતો આપે છે &mdash; <em>Paste into all 7</em> અને <em>Paste into 6 empty cells</em> &mdash; જેથી તમે કમિટ કરતાં પહેલાં પસંદગી કરો, પછી નહીં. ઓવરરાઇટ કરવાથી પુષ્ટિ માટે પુછાય છે અને તે કેટલી શિફ્ટ બદલશે તે જણાવે છે; ખાલી જગ્યાઓ ભરવાનું આપોઆપ થાય છે, કેમ કે કંઈ ગુમાવાતું નથી. એ જ મેનૂ દિવસ, અઠવાડિયું કે પસંદગીને <strong>સાફ</strong> પણ કરે છે, ફરીથી તે કેટલી શિફ્ટ દૂર કરશે તે જણાવ્યા પછી.',
            'rota_step5' => '<strong>એક વ્યક્તિ માટે આખો દિવસ કે આખું અઠવાડિયું કૉપિ કરો</strong> &mdash; તે દિવસની બધી શિફ્ટ ઉપાડવા માટે <strong>દિવસના હેડિંગ</strong> પર રાઇટ-ક્લિક કરો અને <em>Copy</em> પસંદ કરો, અથવા તેમનું આખું અઠવાડિયું ઉપાડવા માટે <strong>વિશ્લેષકના નામ</strong> પર. બીજા દિવસ પર, અથવા બીજા વિશ્લેષક પર પેસ્ટ કરવાથી તે મેળ ખાય છે: જે શિફ્ટ કૉપિમાં ન હતી તે સાફ થઈ જાય છે, જેથી તમને બંનેનું મિશ્રણ નહીં પણ તમે કૉપિ કરેલો દિવસ મળે છે. દિવસ ફક્ત બીજા દિવસ પર જ પેસ્ટ થઈ શકે છે અને વિશ્લેષક ફક્ત બીજા વિશ્લેષક પર જ &mdash; દિવસ એટલે <em>વ્યક્તિ દીઠ</em> એક શિફ્ટ અને અઠવાડિયું એટલે <em>દિવસ દીઠ</em> એક શિફ્ટ, તેથી એકને બીજા પર મૂકવાની કોઈ સમજદાર રીત નથી. પ્રયાસ કરી જુઓ અને મેનૂ તે કહેશે, અને તેને બદલે ક્યાં જઈ શકાય તે પણ કહેશે.',
            'rota_step6' => '<strong>આખું અઠવાડિયું કૉપિ કરો</strong> &mdash; ટોચે જમણી બાજુના <strong>Copy week</strong> અને <strong>Paste week</strong> તમે જોઈ રહ્યા છો તે અઠવાડિયાની બધી શિફ્ટ ઉપાડીને બીજા પર મૂકે છે, જે રિપીટ થતો રોટા બનાવવાની સૌથી ઝડપી રીત છે. પેસ્ટ કરવાથી લક્ષ્ય અઠવાડિયું <em>બદલાઈ</em> જાય છે, તેથી પુષ્ટિ તમને જણાવે છે કે કેટલી એન્ટ્રી હમણાં દૂર થવાની છે. તે ફક્ત ગ્રિડ ખરેખર જે દિવસો અને લોકો બતાવે છે તેને જ સ્પર્શ કરે છે.',
            'tip' => 'અસરકારક કેપેસિટી પ્લાનિંગ માટે કૅલેન્ડર અને રોટાને સાથે જોડો. જો કૅલેન્ડર દર સોમવારે સવારે ટિકિટોમાં વધારો બતાવે, તો ખાતરી કરો કે તે સ્લોટ માટે રોટામાં વધારાની કવરેજ શેડ્યુલ કરેલી હોય.',
        ],
        'settings' => [
            'heading' => 'સેટિંગ્સ',
            'intro' => 'સેટિંગ્સ પેજ એ છે જ્યાં તમે તમારી ટિકિટિંગ સિસ્ટમના બિલ્ડિંગ બ્લોક્સ ગોઠવો છો. બધા લુકઅપ વેલ્યુ, SLA ટાર્ગેટ, ઈમેઇલ ઇન્ટિગ્રેશન અને કસ્ટમ ફીલ્ડ્સ અહીંથી મેનેજ થાય છે.',
            'sla_callout_title' => 'SLA મેનેજમેન્ટ &mdash; સંપૂર્ણ માર્ગદર્શિકા',
            'sla_callout_body' => 'ગોઠવી શકાય તેવા વિકલ્પો, બિઝનેસ કૅલેન્ડર, પોઝ સ્થિતિઓ, બ્રીચ નોટિફિકેશન, ક્રોન જોબ સેટઅપ, ઉપરાંત સિંગલ-ટાઇમઝોન અને ક્રોસ-ટાઇમઝોન ટીમો માટેના ઉકેલેલા ઉદાહરણો. પોતાનું અલગ પેજ મળવા જેટલું વિસ્તૃત.',
            'card_dept_title' => 'વિભાગો',
            'card_dept_body' => 'IT, HR અને Finance જેવા વિભાગો બનાવો. દરેક વિભાગ ઇનબોક્સમાં એક ફોલ્ડર અને ડેશબોર્ડ પર એક ફિલ્ટર બની જાય છે',
            'card_types_title' => 'ટિકિટ પ્રકારો',
            'card_types_body' => 'તમારો ડેસ્ક જે પ્રકારની વિનંતીઓ સંભાળે છે તે નક્કી કરો: Incident, Service Request, Problem, Change. પ્રકારો વિશ્લેષકોને કામનું વર્ગીકરણ કરવામાં મદદ કરે છે',
            'card_priorities_title' => 'પ્રાથમિકતાઓ',
            'card_priorities_body' => 'નામ, રંગો અને સોર્ટ ક્રમ સાથે પ્રાથમિકતા સ્તરો સેટ કરો. દરેક પ્રાથમિકતા રિસ્પોન્સ અને રિઝોલ્યુશન માટેના SLA ટાર્ગેટ સાથે લિંક થાય છે',
            'card_statuses_title' => 'સ્થિતિઓ',
            'card_statuses_body' => 'ટિકિટ લાઇફસાઇકલના તબક્કાઓ કસ્ટમાઇઝ કરો. ડિફોલ્ટ સ્થિતિઓમાં New, Open, In Progress, Pending, Resolved અને Closed શામેલ છે',
            'card_categories_title' => 'શ્રેણીઓ',
            'card_categories_body' => 'ટેકનિકલ ક્ષેત્ર પ્રમાણે ટિકિટોનું જૂથ બનાવો: Hardware, Software, Network, Access. શ્રેણીઓ રિપોર્ટિંગ બ્રેકડાઉનને શક્તિ આપે છે',
            'card_sla_title' => 'SLA ટાર્ગેટ',
            'card_sla_body' => 'દરેક પ્રાથમિકતા માટે રિસ્પોન્સ અને રિઝોલ્યુશન સમયના ટાર્ગેટ નક્કી કરો. SLA ટાઇમર ટિકિટો પર દેખાય છે અને બ્રીચ ચેતવણીઓ ચલાવે છે',
            'card_email_title' => 'ઈમેઇલ ઈમ્પોર્ટિંગ',
            'card_email_body' => 'ઈમેઇલને નવી ટિકિટો તરીકે આપોઆપ ઈમ્પોર્ટ કરવા માટે એક મેઈલબોક્સ (Exchange, Microsoft 365) કનેક્ટ કરો. જવાબો હાલની ટિકિટોમાં પાછા થ્રેડ થાય છે',
            'card_custom_title' => 'કસ્ટમ ફીલ્ડ્સ',
            'card_custom_body' => 'તમારા સંગઠનને જોઈતો એવો ડેટા મેળવવા માટે ટિકિટોમાં તમારા પોતાના ફીલ્ડ્સ ઉમેરો જે ડિફોલ્ટ ફીલ્ડ સેટમાં આવરી લેવાયેલો નથી',
            'card_templates_title' => 'ઈમેઇલ ટેમ્પ્લેટ્સ',
            'card_templates_body' => 'ટિકિટો બને, અપડેટ થાય, ઉકેલાય ત્યારે અથવા CSAT સર્વે માટે એન્ડ યુઝર્સને મોકલાતા નોટિફિકેશન ટેમ્પ્લેટ્સ ગોઠવો. [requester_name] અને [csat_link] જેવા મર્જ કોડ એમ્બેડ કરો',
            'card_checklists_title' => 'ચેકલિસ્ટ્સ',
            'card_checklists_body' => 'નક્કી કરો કે જ્યારે કોઈ ટિકિટ બંધ કરે જેમાં હજુ ફરજિયાત ચેકલિસ્ટ પગલાં બાકી હોય ત્યારે શું થાય: <strong>ચેતવણી આપો</strong> અને પગલાં તથા કોણે બંધ કરી તેનું નામ આપતી આંતરિક નોંધ રેકોર્ડ કરો, અથવા તે પૂર્ણ ન થાય ત્યાં સુધી <strong>બંધ કરવાનું અટકાવો</strong>. ટિકિટ બંધ કરી શકાય તેવી દરેક જગ્યાએ લાગુ - બલ્ક ક્રિયાઓ, REST API અને વર્કફ્લો ઓટોમેશન સહિત',
            'card_mandatory_title' => 'ફરજિયાત ફીલ્ડ્સ',
            'card_mandatory_body' => 'ટિકિટ બંધ થાય તે પહેલાં ભરવા આવશ્યક ફીલ્ડ્સ ટિક કરો - શ્રેણી, રિઝોલ્યુશન કોડ, માલિક વગેરે. પછી કોઈ ફીલ્ડ ખાલી હોય ત્યારે ટિકિટ બંધ કરવામાં આવે તો શું થાય તે પસંદ કરો: <strong>ચેતવણી આપો</strong>, સર્વિસ ડિલિવરી મેનેજર જેવા કોઈને <strong>ચેતવણી અને ઈમેઇલ</strong> મોકલો, અથવા બંધ કરવાનો <strong>ઇનકાર</strong> કરો. એક અલગ સ્વિચ તેને ટિકિટ પર આંતરિક નોંધ તરીકે રેકોર્ડ કરે છે. કંપની માટે બંધ કરેલું ફીલ્ડ ક્યારેય જરૂરી ગણાતું નથી, અને ટિકિટો મર્જ કરવાથી તે ક્યારેય ટ્રિગર થતું નથી. ટિકિટ બંધ થઈ શકે તેવી દરેક જગ્યાએ લાગુ - બલ્ક એક્શન, REST API અને વર્કફ્લો ઓટોમેશન સહિત',
            'card_cleanup_title' => 'Reply Cleanup AI',
            'card_cleanup_body' => 'રિપ્લાય એડિટર પરના ✨ Cleanup બટન માટે Anthropic કી + મોડેલ + ટોન. ગ્રાન્યુલર બિલિંગ માટે અન્ય AI ફીચર્સથી અલગ કી',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'મોકલવાની રીત (off / auto / manual), વિલંબ, વન-પર-ટિકિટ ગાર્ડ, સ્કેલ (સ્ટાર્સ કે ઇમોજી). સંપૂર્ણ ફ્લો માટે સેક્શન 6 જુઓ',
            'email_heading' => '<strong>ઈમેઇલ ઈમ્પોર્ટિંગ વિગતવાર</strong>',
            'email_body' => 'ઈમેઇલ ઈમ્પોર્ટ ફીચર તમારા શેર કરેલા મેઈલબોક્સ સાથે કનેક્ટ થાય છે અને નવા મેસેજને ટિકિટો તરીકે ખેંચી લાવે છે. જ્યારે કોઈ એન્ડ યુઝર તમારા સપોર્ટ સરનામે (દા.ત. support@yourcompany.com) ઈમેઇલ મોકલે છે, ત્યારે FreeITSM ઈમેઇલના વિષયને શીર્ષક તરીકે અને ઈમેઇલના બોડીને વર્ણન તરીકે લઈને ટિકિટ બનાવે છે. જો મોકલનાર નોટિફિકેશન ઈમેઇલનો જવાબ આપે, તો તે જવાબ ડુપ્લિકેટ બનાવવાને બદલે હાલની ટિકિટમાં થ્રેડ થાય છે.',
            'email_step1' => '<strong>મેઈલબોક્સ ગોઠવો</strong> &mdash; Settings પર જાઓ અને તમારા Exchange અથવા Microsoft 365 ક્રેડેન્શિયલ્સ દાખલ કરો. સુરક્ષિત, પાસવર્ડ-રહિત કનેક્શન માટે OAuth ઓથેન્ટિકેશન સપોર્ટેડ છે.',
            'email_step2' => '<strong>પોલિંગ ઇન્ટરવલ સેટ કરો</strong> &mdash; FreeITSM નવા મેસેજ માટે મેઈલબોક્સ કેટલી વારંવાર તપાસે તે પસંદ કરો. ટૂંકા ઇન્ટરવલનો અર્થ ઝડપી ટિકિટ સર્જન છે.',
            'email_step3' => '<strong>ડિફોલ્ટ મેપ કરો</strong> &mdash; ઈમેઇલમાંથી બનેલી ટિકિટો માટે ડિફોલ્ટ વિભાગ, પ્રકાર અને પ્રાથમિકતા સેટ કરો. ઈમ્પોર્ટ પછી વિશ્લેષકો આને ગોઠવી શકે છે.',
            'tip' => 'બધા એન્ડ-યુઝર કમ્યુનિકેશનમાં પ્રોફેશનલ, સુસંગત ટોન જાળવવા માટે ઈમેઇલ ટેમ્પ્લેટ્સનો ઉપયોગ કરો. ટેમ્પ્લેટ્સ ટિકિટ સંદર્ભ, વિનંતી કરનારનું નામ, વિશ્લેષકનું નામ અને સ્થિતિ માટે ડાયનેમિક પ્લેસહોલ્ડર્સ સપોર્ટ કરે છે.',
            'closemsg_heading' => '<strong>ટિકિટ બંધ કરો ત્યારે એક વખતનો સંદેશ</strong>',
            'closemsg_body' => 'સક્રિય <strong>Ticket closed</strong> ટેમ્પ્લેટમાં ગમે ત્યાં <code>[ticket_closed_message]</code> મૂકો અને, ત્યારપછી, ટિકિટને બંધ સ્થિતિમાં સેટ કરવાથી વિશ્લેષકને એક વાક્ય પૂછવામાં આવશે - <em>&ldquo;the spare charger is on your desk&rdquo;</em>, <em>&ldquo;closing as agreed on the phone&rdquo;</em>. તેઓ જે પણ ટાઇપ કરે તે બરાબર જ્યાં તમે પ્લેસહોલ્ડર મૂક્યો છે ત્યાં જ આવે છે, જેથી તેની આસપાસના શબ્દો પર તમારો કાબૂ રહે છે. આ કોઈ સેટિંગ નથી અને તેને કંઈ સ્ટોર કરતું નથી: એક નોંધ, એક ટિકિટ, એક ઈમેઇલ. કંઈ ટાઇપ ન કરો તો તે લાઇન ત્યાં હોતી જ નથી - કોઈ ગેપ નહીં, કોઈ છૂટું વિરામચિહ્ન નહીં.',
            'closemsg_note' => '<strong>પ્રોમ્પ્ટ ત્યારે જ દેખાય છે જ્યારે ટેમ્પ્લેટમાં ખરેખર પ્લેસહોલ્ડર હોય.</strong> તેના વગર, વિશ્લેષકે જે પણ ટાઇપ કર્યું હોય તે ચૂપચાપ ફેંકાઈ જાય, અને જે દરેક ડેસ્કને આ જોઈતું નથી તેને દરેક બંધ કરવા પર એક વધારાનો ક્લિક મળે. તેથી જ્યારે તમે તેને ગોઠવો ત્યારે તે જાતે ચાલુ થાય છે અને જ્યારે તમે ન ગોઠવ્યું હોય ત્યારે તે આડે આવતું નથી.',
            'cat_heading' => '<strong>શ્રેણીઓ, અને તેમની બાજુના બે ફીલ્ડ્સ</strong>',
            'cat_body' => 'ટિકિટનો <em>type</em> જણાવે છે કે આ કેવા પ્રકારની બાબત છે; <em>category</em> જણાવે છે કે તે શેના વિશે છે. <strong>Settings &rarr; Categories</strong> હેઠળ યાદી બનાવો, સાથે એ સ્વિચ પણ કે જે નક્કી કરે છે કે તેમાંથી કંઈ ટિકિટ પર દેખાય કે નહીં.',
            'cat_card_one_title' => 'શ્રેણી',
            'cat_card_one_body' => 'ટિકિટ કયા રૂપે નોંધાવવામાં આવી હતી, જે તેને ઉઠાવતી વખતે પસંદ કરવામાં આવે છે. એક ટિકિટ પાસે બરાબર એક જ હોય છે, તેથી તમારી શ્રેણીઓનો રિપોર્ટ હંમેશા તમારી પાસે ખરેખર જેટલી ટિકિટો હતી તેટલી જ સંખ્યામાં ઉમેરાય છે.',
            'cat_card_close_title' => 'બંધ સમયની કેટેગરી',
            'cat_card_close_body' => 'ટિકિટ પૂરી થાય ત્યારે એ જ યાદી ફરીથી પુછાય છે. સામાન્ય રીતે વિશ્લેષક ફક્ત તેની પુષ્ટિ કરે છે &mdash; તે એવા કિસ્સાઓમાં પોતાનું સ્થાન કમાય છે જ્યાં પહેલો અંદાજ ખોટો હતો, જેનાથી તમને ખબર પડે છે કે તમારી સાડત્રીસ "printer problems" માંથી બાર ખરેખર નેટવર્કની સમસ્યા હતી.',
            'cat_card_res_title' => 'રિઝોલ્યુશન કોડ',
            'cat_card_res_body' => 'ટિકિટ શેના વિશે હતી તેના બદલે તે કેવી રીતે પૂરી થઈ &mdash; "Fixed remotely", "Training given", "No fault found". શરૂઆતથી જ દસ સમજદાર વિકલ્પો ત્યાં હોય છે અને તમે તે બધા બદલી શકો છો.',
            'cat_rule_off' => '<strong>ત્રણેય શરૂઆતમાં બંધ હોય છે.</strong> પહેલાં તમારી યાદી બનાવો, પછી જે જોઈએ તે ચાલુ કરો. દરેકને દરેક કંપની માટે અલગ રીતે સેટ કરી શકાય છે.',
            'cat_rule_levels' => 'શ્રેણીઓમાં ત્રણ સ્તર સુધી સબ-કેટેગરી હોઈ શકે છે, અને કોઈ સ્તર ફરજિયાત નથી.',
            'cat_rule_type' => 'શ્રેણીને એક ટિકિટ પ્રકાર સાથે જોડી શકાય છે, જેથી "User onboarding" ફક્ત સર્વિસ રિક્વેસ્ટ પર જ ઓફર થાય છે. આ જોડાણ ટોપ-લેવલ શ્રેણીનું હોય છે અને તેની સબ-કેટેગરીઓ તેને અનુસરે છે.',
            'cat_rule_typechange' => '<strong>ટિકિટનો પ્રકાર બદલવાથી જૂના પ્રકાર સાથે જોડાયેલી શ્રેણી સાફ થઈ જાય છે</strong>, અને સ્ક્રીન પર તે જણાવાય છે. કોઈ પ્રકાર સાથે ન જોડાયેલી શ્રેણી ફેરફાર છતાં ટકી રહે છે.',
            'cat_rule_portal' => 'સેલ્ફ-સર્વિસ પોર્ટલમાં શ્રેણી ઓફર કરવા માટે <em>Customers can pick this</em> ટિક કરો. વિનંતી કરનારાઓ સાદી ભાષામાં ટૂંકી યાદી જુએ છે જ્યારે વિશ્લેષકો આખું ટ્રી જુએ છે.',
            'cat_rule_retire' => 'શ્રેણીને રિટાયર કરવા માટે તેને બંધ કરો &mdash; તે પહેલેથી જેની પાસે છે તે ટિકિટો પર રહે છે અને નવી ટિકિટો પર ઓફર થવાનું બંધ થાય છે. તે લગભગ હંમેશા ડિલીટ કરવા કરતાં સારું છે, જેને કંઈ પણ હજુ વાપરતું હોય ત્યાં સુધી નકારવામાં આવે છે.',
            'cat_rule_report' => 'ત્રણેયને ટિકિટ ડેશબોર્ડ પર ચાર્ટ કરી શકાય છે. બંને શ્રેણી ચાર્ટ ટોપ લેવલ સુધી રોલ અપ થાય છે, અને જે ટિકિટોમાં કંઈ સેટ નથી તે છુપાવવાને બદલે <em>Not categorised</em> તરીકે ગણાય છે.',
            'cat_tip' => 'જો તમને ખાતરી ન હોય કે ક્યાંથી શરૂ કરવું, તો શ્રેણીઓ ખાલી રહેવા દો અને એકલા <strong>Resolution code</strong>ને ચાલુ કરો. તે એવું ફીલ્ડ છે જે તમે શું કરો છો તે સૌથી ઝડપથી બદલે છે &mdash; તમારી પાંચમા ભાગની ટિકિટો "Training given" તરીકે પાછી આવવી એ ડોક્યુમેન્ટેશનની સમસ્યા છે, IT ની નહીં.',
        ],
        'tips' => [
            'heading' => 'ઝડપી ટિપ્સ',
            'search_title' => 'બધું શોધો',
            'search_body' => 'સર્ચ મોડલ ટિકિટ સંદર્ભ, વિષયો, વિનંતી કરનારના નામ અને ઈમેઇલ સરનામાં તપાસે છે. જ્યારે કોઈ યુઝર હાલની સમસ્યા વિશે કૉલ કરે ત્યારે સંબંધિત ટિકિટો ઝડપથી શોધવા માટે તેનો ઉપયોગ કરો.',
            'sla_title' => 'તમારા SLA પર નજર રાખો',
            'sla_body' => 'SLA ટાઇમર રીડિંગ પેનમાં દરેક ટિકિટ પર દેખાય છે. જ્યારે બ્રીચ નજીક આવે ત્યારે કલર-કોડેડ ઇન્ડિકેટર એમ્બર થાય છે અને ટાર્ગેટ ચૂકી જાય ત્યારે લાલ, જેથી તમે તે પ્રમાણે પ્રાથમિકતા આપી શકો.',
            'reply_title' => 'ઇનબોક્સમાંથી જવાબ આપો',
            'reply_body' => 'એન્ડ યુઝરને જવાબ આપવા માટે તમારે તમારો ઈમેઇલ ક્લાયન્ટ ખોલવાની જરૂર નથી. સીધો મેસેજ મોકલવા માટે રીડિંગ પેનમાંનું Reply બટન વાપરો. તે આપોઆપ ટિકિટમાં થ્રેડ થાય છે.',
            'trail_title' => 'એક્ટિવિટી ટ્રેલનો ઉપયોગ કરો',
            'trail_body' => 'ટિકિટ પર કામ કરતાં પહેલાં, તેની એક્ટિવિટી ટ્રેલ સ્ક્રોલ કરો. અગાઉના વિશ્લેષકની નોંધો, ઈમેઇલ અને ફીલ્ડ ફેરફારો તમને પૂરો સંદર્ભ આપે છે જેથી તમારે યુઝરને માહિતી ફરીથી કહેવાનું ન કહેવું પડે.',
            'dash_title' => 'મેનેજરો માટે ડેશબોર્ડ',
            'dash_body' => 'SLA કમ્પ્લાયન્સ રેટ, સરેરાશ રિઝોલ્યુશન સમય અને વિભાગ પ્રમાણે ટિકિટો માટેના વિજેટ્સ સાથે ડેશબોર્ડ બનાવો. સતત સુધારો લાવવા માટે ટીમ મીટિંગમાં તેને શેર કરો.',
            'rota_title' => 'રોટા સાથે આયોજન કરો',
            'rota_body' => 'ઓછામાં ઓછા બે અઠવાડિયા અગાઉથી રોટા ભરો. કૅલેન્ડર દૃશ્ય સાથે જોડાયેલું હોય ત્યારે, તે કવરેજમાંના ગેપ રિસ્પોન્સ સમય માટે સમસ્યા બને તે પહેલાં ઓળખવામાં મદદ કરે છે.',
            'drag_title' => 'ટ્રાયેજ કરવા ડ્રેગ કરો',
            'drag_body' => 'ટિકિટો ખોલ્યા વગર અપડેટ કરવા માટે તેમને યાદીમાંથી ફોલ્ડર પર ડ્રેગ કરો. Department + status સબ-ફોલ્ડર બંનેને એકસાથે અપડેટ કરે છે. સ્પ્રિંગ-લોડેડ એક્સપાન્શન ડ્રેગ કરતી વખતે જ નેસ્ટેડ સ્થિતિઓ સુધી પહોંચવા દે છે.',
            'dbl_title' => 'ફુલ સ્ક્રીન માટે ડબલ-ક્લિક કરો',
            'dbl_body' => 'સિંગલ-ક્લિક રીડિંગ પેનમાં ટિકિટનું પ્રિવ્યૂ બતાવે છે; ડબલ-ક્લિક ફોકસ કામ માટે તેને ફુલ-સ્ક્રીન મોડમાં ખોલે છે. પાછા ટૉગલ કરવા માટે વિષયની બાજુના મેક્સિમાઇઝ આઇકન પર ક્લિક કરો.',
            'rightclick_title' => 'ઝડપી ક્રિયાઓ માટે રાઇટ-ક્લિક કરો',
            'rightclick_body' => 'તમે અત્યારે વાંચી રહ્યા છો તે ટિકિટથી ખસ્યા વગર જ, વન-ક્લિક સ્થિતિ, પ્રાથમિકતા કે સોંપાયેલ વ્યક્તિમાં ફેરફાર ઉપરાંત link-CMDB અને record-time માટે કોઈ પણ ટિકિટ પર રાઇટ-ક્લિક કરો.',
            'ai_title' => 'AI ને તમારો જવાબ સુધારવા દો',
            'ai_body' => 'એક કાચો ડ્રાફ્ટ (અથવા ફક્ત બુલેટ પોઇન્ટ્સ) ટાઇપ કરો અને <strong>✨ Cleanup</strong> પર ક્લિક કરો &mdash; Claude તેને ગ્રીટિંગ, વ્યાકરણ સુધારા અને સાઇન-ઑફ સાથે યોગ્ય ઈમેઇલ તરીકે ફરીથી લખે છે. 30 સેકન્ડ માટે Undo લિંક દેખાય છે.',
            'feedback_title' => 'ફીડબેક માંગો',
            'feedback_body' => 'વિનંતી કરનારાઓની ટિકિટ બંધ થાય ત્યારે ઑટો-સર્વે કરવા માટે <strong>Settings &rarr; CSAT</strong> હેઠળ CSAT ચાલુ કરો. પ્રતિ-વિશ્લેષક ટ્રેન્ડ્સ <code>tickets/csat/</code> પર રહે છે &mdash; ડેવલપમેન્ટ વાતચીતો માટે સોના જેવા.',
            'precreate_title' => 'એન્ડ યુઝર્સને પહેલેથી બનાવો',
            'precreate_body' => '<strong>Users</strong> નેવ બટન તમને યુઝરને ટિકિટ લોગ કરવાની જરૂર પડે તે પહેલાં ઉમેરવા દે છે &mdash; પાસવર્ડ ખાલી રાખો અને તેઓ સેલ્ફ-સર્વિસ પોર્ટલ મારફતે જાતે એકાઉન્ટ ક્લેમ કરી શકે.',
        ],
        'companies' => [
            'heading' => 'કંપનીઓ &amp; ઈમેઇલ રાઉટિંગ',
            'intro' => 'જ્યારે તમારું ઇન્સ્ટોલ એક કરતાં વધુ કંપનીને સેવા આપે છે (દાખલા તરીકે, અનેક ક્લાયન્ટને સપોર્ટ કરતો IT પ્રોવાઇડર), ત્યારે દરેક કંપનીની ટિકિટો અલગ રાખવામાં આવે છે. આ સેક્શન સમજાવે છે કે ઇનબાઉન્ડ ઈમેઇલ સાચી કંપની કેવી રીતે શોધે છે.',
            'switcher_body' => 'હેડરમાં એક <strong>કંપની સ્વિચર</strong> દેખાય છે. તે તમે કઈ કંપનીમાં કામ કરી રહ્યા છો તે નક્કી કરે છે &mdash; ટિકિટ યાદી, ફોલ્ડર અને ગણતરીઓ ફક્ત તે જ કંપની બતાવે છે, અને તમે બનાવો છો તે કોઈ પણ ટિકિટ તેમાં ફાઇલ થાય છે. અનેક કંપનીની ઍક્સેસ ધરાવતો સ્ટાફ તેમની વચ્ચે સ્વિચ કરી શકે છે; વર્તમાન કંપની હંમેશા બતાવાય છે જેથી તમે ખોટા સંદર્ભમાં જવાબ ન આપો. <strong>System &rarr; Companies</strong> હેઠળ કંપનીઓનું જ સંચાલન કરો.',
            'mailboxes_heading' => 'દરેક મેઈલબોક્સ બે પ્રકારમાંથી એક હોય છે &mdash; આ જ રાઉટિંગ નક્કી કરે છે:',
            'card_pinned_title' => 'પિન કરેલ મેઈલબોક્સ',
            'card_pinned_body' => 'એક કંપની માટે સમર્પિત (દા.ત. ક્લાયન્ટનું પોતાનું <code>itsupport@</code>). તેની <strong>બધી</strong> મેઇલ તે કંપનીમાં ફાઇલ થાય છે &mdash; મોકલનારને અવગણવામાં આવે છે &mdash; અને જવાબો પણ તેમાંથી જ પાછા જાય છે, જેથી ક્લાયન્ટને શરૂઆતથી અંત સુધી પોતાનો જ હેલ્પ ડેસ્ક દેખાય.',
            'card_shared_title' => 'શેર કરેલ ઇનટેક મેઈલબોક્સ',
            'card_shared_body' => 'એક જ સરનામું અનેક કંપનીઓને સેવા આપે છે (દા.ત. પ્રોવાઇડરનું એક જ <code>support@theprovider.com</code>). તે ફક્ત સરનામા પરથી કંપની જાણી શકતું નથી, તેથી તે <strong>ઈમેઇલ કોણે મોકલ્યો</strong> તેના પરથી નક્કી કરે છે. અનેક ક્લાયન્ટ ધરાવતા પ્રોવાઇડર માટે ભલામણ કરેલ સેટઅપ.',
            'routing_heading' => 'શેર કરેલ ઇનટેક મેઈલબોક્સ કંપની કેવી રીતે પસંદ કરે છે',
            'routing_body' => 'દરેક આવતા ઈમેઇલ માટે તે આ ક્રમમાં અજમાવે છે, અને પહેલો મેચ જીતે છે:',
            'flow_reply' => 'ટિકિટનો જવાબ',
            'flow_sender' => 'જાણીતો મોકલનાર',
            'flow_domain' => 'જાણીતો ડોમેન',
            'flow_triage' => 'ટ્રાયેજ',
            'rule_reply' => '<strong>1. હાલની ટિકિટનો જવાબ</strong> &mdash; તેના સંદર્ભ પરથી ઓળખાય છે, ઈમેઇલ તે ટિકિટમાં જોડાય છે અને તેની કંપની જ રાખે છે.',
            'rule_sender' => '<strong>2. કોઈ ચોક્કસ મોકલનાર સરનામું</strong> કંપની સાથે મેપ થયેલું (દા.ત. <code>jane@gmail.com</code> &rarr; Acme) &mdash; તે કંપની. ડોમેન પહેલાં તપાસાય છે, તેથી તે વ્યક્તિગત/વેબમેઇલ સરનામાં માટે પણ કામ કરે છે.',
            'rule_domain' => '<strong>3. મોકલનારનો ડોમેન</strong> કંપની સાથે મેપ થયેલો (દા.ત. <code>@acme.com</code> પરથી કોઈ પણ &rarr; Acme) &mdash; તે કંપની.',
            'rule_triage' => '<strong>4. કોઈ મેચ નહીં</strong> &mdash; ઈમેઇલ ખોવાઈ જવાને બદલે <strong>ટ્રાયેજ</strong> ક્યૂમાં જાય છે (નીચે જુઓ).',
            'keys_heading' => 'ડોમેન &amp; ચોક્કસ મોકલનારા (System &rarr; Companies હેઠળ કંપની દીઠ સેટ કરેલા)',
            'keys_body' => 'શેર કરેલ ઇનટેક મેઈલબોક્સ જે કીઓ પર મેચ કરે છે તે આ છે. દરેક કંપની પોતાની માલિકીના ઈમેઇલ ડોમેન અને, વૈકલ્પિક રીતે, વ્યક્તિગત મોકલનાર સરનામાંની યાદી બનાવે છે.',
            'card_domains_title' => 'ઈમેઇલ ડોમેન',
            'card_domains_body' => 'કંપનીની માલિકીના ડોમેન (acme.com, acme.co.uk). રજિસ્ટર્ડ ડોમેન પરનો કોઈ પણ મોકલનાર તે કંપની પર રાઉટ થાય છે. એક ડોમેન ફક્ત એક જ કંપનીનો હોય છે.',
            'card_senders_title' => 'ચોક્કસ મોકલનારા',
            'card_senders_body' => 'વ્યક્તિગત સરનામાં જે કંપની સાથે મેપ થયેલા છે, ડોમેન પહેલાં તપાસાય છે. વ્યક્તિગત સરનામેથી ઈમેઇલ કરતા ફ્રીલાન્સર કે નાના ક્લાયન્ટ માટે તેનો ઉપયોગ કરો.',
            'card_public_title' => 'પબ્લિક પ્રોવાઇડર્સ',
            'card_public_body' => 'Gmail, Outlook, Yahoo અને તેના જેવાને ડોમેન તરીકે મેપ કરી શકાતા નથી (અનેક અસંબંધિત લોકો તેમને શેર કરે છે) &mdash; તેને બદલે ચોક્કસ સરનામાને ચોક્કસ મોકલનાર તરીકે મેપ કરો.',
            'triage_heading' => 'ટ્રાયેજ ક્યૂ &mdash; સેફ્ટી નેટ',
            'triage_body' => 'જ્યારે શેર કરેલ ઇનટેક ઈમેઇલ કોઈ કંપની સાથે મેચ ન થાય ત્યારે તે ખોવાઈ જવાને બદલે <strong>Triage</strong> માં પડે છે (કંપની સ્વિચરથી પહોંચી શકાય છે, લાઇવ કાઉન્ટ સાથે). દરેક આઇટમ મોકલનાર, ડોમેન, વિષય અને તે કયા મેઈલબોક્સ પર આવ્યો તે બતાવે છે. તેને એક જ પગલામાં કંપનીમાં ફાઇલ કરો:',
            'triage_create' => 'હાલની કંપની પસંદ કરો, અથવા તરત જ નવી બનાવો.',
            'triage_assign' => 'સામાન્ય ડોમેન માટે, ઇચ્છા મુજબ તે <strong>ડોમેનને કંપની પર રાઉટ કરો</strong>; પબ્લિક/વેબમેઇલ સરનામા માટે, ઇચ્છા મુજબ તે <strong>મોકલનારને હંમેશા</strong> ત્યાં ફાઇલ કરો.',
            'triage_sweep' => 'બેમાંથી કોઈ પણ પસંદગી <em>sweep</em> કરે છે: તે તે ડોમેન કે સરનામામાંથી ક્યૂમાં રહેલા બીજા બધા ઈમેઇલ પણ ખસેડે છે, અને ભવિષ્યની મેઇલને ઑટો-રાઉટ કરે છે &mdash; જેથી તમારે કોઈ મોકલનારને ફક્ત એક જ વાર સૉર્ટ કરવાનું રહે.',
            'triage_tip' => 'કંઈ પણ ક્યારેય ખોવાતું નથી. મેચ ન થયેલી મેઇલ ટ્રાયેજમાં રાહ જુએ છે જ્યાં સુધી કોઈ તેને ફાઇલ ન કરે; દરમિયાન, ફાઇલ ન થયેલી ટિકિટ ડિફોલ્ટ કંપની હેઠળ જ દેખાય છે.',
            'test_heading' => 'લાઇવ જવા પહેલાં તમારું રાઉટિંગ ટેસ્ટ કરો',
            'test_body' => '<strong>System &rarr; Email routing test</strong> હેઠળ તમે ડોળ કરી શકો છો કે એક ઈમેઇલ આવ્યો &mdash; મેઈલબોક્સ પસંદ કરો, મોકલનારનું સરનામું ટાઇપ કરો &mdash; અને બરાબર જુઓ કે નવી ટિકિટ કઈ કંપનીમાં જશે (અથવા ટ્રાયેજમાં જશે) અને કયા નિયમે તે નક્કી કર્યું. તે કંઈ બનાવતું નથી; તે ફક્ત તમારી સેટિંગ્સ વાંચે છે.',
            'settings_heading' => 'સેટિંગ્સ: ડિફોલ્ટ રીતે શેર્ડ, જ્યાં જરૂરી હોય ત્યાં કસ્ટમાઇઝ્ડ',
            'settings_body' => 'આમાંની કેટલીક સેટિંગ્સને <strong>કંપની પ્રમાણે કસ્ટમાઇઝ</strong> કરી શકાય છે; બાકીની ઇરાદાપૂર્વક શેર્ડ રહે છે. જ્યાં સેટિંગ વિકલ્પોની સાદી યાદી હોય &mdash; જેમ કે <strong>ticket types</strong> અને <strong>origins</strong> &mdash; ત્યાં કંપનીના સંદર્ભમાં સ્વિચ કરો અને તમને શેર્ડ ડિફોલ્ટ દેખાશે (દરેકની સાથે ન વાપરતું હોય તેને છુપાવવા માટે એક આઇ આઇકન) ઉપરાંત તેણે પોતાના માટે જ ઉમેરેલા કોઈ પણ વિકલ્પો. જ્યાં સુધી ખુલ્લી ટિકિટો કોઈ વિકલ્પ વાપરતી હોય ત્યાં સુધી તમે તેને છુપાવી કે ડિલીટ કરી શકતા નથી, અને શેર્ડ ડિફોલ્ટ પોતે MSP / ડિફોલ્ટ કંપનીમાંથી સંપાદિત થાય છે.',
            'settings_custom_title' => 'કંપની પ્રમાણે કસ્ટમાઇઝ્ડ',
            'settings_custom_body' => 'Ticket types &amp; origins (હમણાં), અને categories, SLAs &amp; business hours (આવી રહ્યું છે) &mdash; એવી બાબતો જે ખરેખર એક ક્લાયન્ટથી બીજા ક્લાયન્ટમાં અલગ હોય છે.',
            'settings_global_title' => 'દરેક કંપનીમાં શેર્ડ',
            'settings_global_body' => 'સ્થિતિઓ અને પ્રાથમિકતાઓ દરેક જગ્યાએ સરખી રહે છે, જેથી ક્રોસ-કંપની રિપોર્ટિંગ અને SLA સુસંગત રહે; તમારી ટીમો, રોટા અને મેઈલબોક્સ પણ એવા જ &mdash; આ તમારું પોતાનું ઓપરેશન છે, ક્લાયન્ટનું નહીં.',
            'allview_heading' => '<strong>દરેક કંપનીમાં એક જ બોર્ડ</strong>',
            'allview_body' => 'હેડરમાંના કંપની સ્વિચરમાં એક <strong>All companies</strong> વિકલ્પ છે. તમને જોવાની પરવાનગી હોય તેવી દરેક ટિકિટ એક જ યાદીમાં દેખાય છે, દરેક પંક્તિ પોતાની કંપની સાથે &mdash; જ્યારે તમે અનેક એન્ટિટીને સપોર્ટ કરો છો અને કોનું શું છે તે ગુમાવ્યા વગર દિવસનું એક જ દૃશ્ય જોઈતું હોય ત્યારે ઉપયોગી.',
            'allview_card_scope_title' => 'તે કંઈ નવું આપતું નથી',
            'allview_card_scope_body' => '"All" નો અર્થ છે તમે એક સમયે એક-એક કરીને પહેલેથી પહોંચી શકતા હતા તે દરેક કંપની. તમારી ત્રણ એન્ટિટીમાંથી બેને સપોર્ટ કરતો વિશ્લેષક બરાબર તે બે જ જુએ છે, અને એક કંપની ધરાવતો વિશ્લેષક તે એક જ કંપનીનું દૃશ્ય જુએ છે.',
            'allview_card_props_title' => 'દરેક એન્ટિટી અલગ રહે છે',
            'allview_card_props_body' => 'ટિકિટ ખોલો અને તેના type, origin, category અને resolution ની યાદી <em>તે જ</em> કંપનીની હોય છે &mdash; જેથી એક એન્ટિટી પાસે હોય અને બીજા પાસે ન હોય તેવી શ્રેણી ક્યારેય ખોટી ટિકિટ પર લાગુ થઈ શકતી નથી.',
            'allview_card_new_title' => 'નવી ટિકિટો પૂછે છે કે કઈ કંપની',
            'allview_card_new_body' => 'ધારી લેવા માટે કોઈ એક જ સક્રિય કંપની હોતી નથી, અને પસંદગી ટિકિટ નંબર, જવાબો જેમાંથી આવે છે તે મેઈલબોક્સ અને લાગુ પડતું SLA નક્કી કરે છે. તમે પસંદગી કરો પછી type ની યાદી ભરાય છે.',
            'allview_rule_chip' => 'ઈમેઇલ કે પોર્ટલ મારફતે આવેલી અને હજુ રાઉટ ન થયેલી ટિકિટ Default હેઠળ બતાવવાને બદલે <strong>Unrouted</strong> તરીકે ચિહ્નિત થાય છે, જેથી તે ટ્રાયેજ માટે અલગ તરી આવે.',
            'allview_rule_reply' => 'જવાબો હજુ પણ ટિકિટ જે મેઈલબોક્સ પર આવી હતી ત્યાંથી જ જાય છે &mdash; આ દૃશ્યને નહીં, ટિકિટને અનુસરે છે, જેથી કૉમ્બાઇન્ડ બોર્ડ ક્યારેય ખોટા સરનામેથી ન મોકલી શકે.',
            'allview_rule_knowledge' => 'કૉમ્બાઇન્ડ દૃશ્ય ચાલુ હોય ત્યારે <strong>Ask AI</strong> ફક્ત એક જ નહીં, પણ તમે જોઈ શકો છો તે દરેક કંપનીમાં શોધે છે. બધી કંપનીઓ સાથે શેર કરેલા લેખો બંને રીતે સામેલ થાય છે.',
            'allview_rule_trash' => '<strong>ટ્રેશ ખાલી કરવાનું ક્યારેય કંપનીઓ વચ્ચે ફેલાતું નથી.</strong> તે હંમેશા તમે છેલ્લે પસંદ કરેલી એક જ કંપનીને લાગુ પડે છે, કારણ કે એકસાથે અનેક એન્ટિટીમાં "bin ની દરેક વસ્તુ ડિલીટ કરો" નો કોઈને એવો અર્થ અભિપ્રેત નથી.',
            'allview_rule_other' => 'ફક્ત ટિકિટ યાદી જ વિસ્તરે છે. Assets, changes, tasks અને CMDB હજુ પણ એક સમયે એક જ કંપની બતાવે છે &mdash; તેમાં કામ કરવા માટે તે કંપની પર સ્વિચ કરો.',
            'privacy_heading' => 'દરેક કંપનીની ટિકિટો ખાનગી રહે છે',
            'privacy_body' => 'જ્યારે તમે કોઈ કંપનીના સંદર્ભમાં કામ કરી રહ્યા હો ત્યારે તમે ફક્ત <strong>તે જ</strong> કંપનીની ટિકિટો જુઓ છો &mdash; યાદીમાં, સર્ચમાં, ડેશબોર્ડ પર, અને તમે ખોલો છો તે દરેક ટિકિટ પર (તેની ઈમેઇલ, જોડાણો, નોંધો અને ઇતિહાસ સહિત). કોઈ સ્ટાફ સભ્ય ટિકિટ સુધી ત્યારે જ પહોંચી શકે છે જ્યારે તેમને તેની કંપનીની ઍક્સેસ આપવામાં આવી હોય (તમે System &rarr; Analysts હેઠળ દરેક વિશ્લેષકની કંપનીઓ પસંદ કરો છો, અથવા System &rarr; Teams પર આખી ટીમને આપો છો), તેથી બીજા ક્લાયન્ટના ડેટામાં ભટકી જવાનો કોઈ રસ્તો નથી. આ અલગતા ફક્ત દૃશ્યથી છુપાવેલી નથી, પડદા પાછળ દરેક જગ્યાએ લાગુ કરવામાં આવે છે. સિંગલ-કંપની ઇન્સ્ટોલ પર તે આપોઆપ અને અદ્રશ્ય છે &mdash; ત્યાં ફક્ત એક જ કંપની હોય છે, તેથી બધું જ સીધું તેની જ હોય છે.',
            'tip' => 'સિંગલ-કંપની ઇન્સ્ટોલ પર આમાંનું કંઈ પણ દેખાતું નથી &mdash; ત્યાં એક કંપની હોય છે, દરેક ટિકિટ તેની જ હોય છે, અને કોઈ સ્વિચર કે ટ્રાયેજ હોતા નથી. બીજી કંપની અસ્તિત્વમાં આવે ત્યારે જ આ ફીચર્સ ચાલુ થાય છે.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'સર્વિસ ડેસ્ક - SLA મેનેજમેન્ટ',
        'back_link' => '&larr; ટિકિટ માર્ગદર્શિકા પર પાછા',
        'sidebar_title' => 'SLA માર્ગદર્શિકા',
        'hero_title' => 'SLA મેનેજમેન્ટ',
        'hero_sub' => 'કામકાજના કલાકોને ધ્યાનમાં રાખતા પ્રતિસાદ અને નિરાકરણ ટાર્ગેટ, વિભાગ પ્રમાણે ભંગ સૂચનાઓ સાથે',
        'nav' => [
            'overview' => 'ઝાંખી',
            'building_blocks' => 'બિલ્ડિંગ બ્લોક્સ',
            'behaviour_settings' => 'વર્તન સેટિંગ્સ',
            'breach_notifications' => 'ભંગ સૂચનાઓ',
            'cron_setup' => 'ક્રોન જોબ સેટઅપ',
            'worked_examples' => 'ઉદાહરણો',
            'troubleshooting' => 'મુશ્કેલીનિવારણ',
        ],
        'overview' => [
            'heading' => 'ઝાંખી',
            'sub' => 'SLA શું છે, તે શા માટે મહત્વના છે, અને FreeITSM એન્જિન ઉચ્ચ સ્તરે કેવી રીતે કામ કરે છે.',
            'p1' => 'સર્વિસ લેવલ એગ્રીમેન્ટ (SLA) એ વચન છે કે તમારી ટીમ ટિકિટનો કેટલી ઝડપથી પ્રતિસાદ આપશે અને તેનું નિરાકરણ કરશે. FreeITSM દરેક ટિકિટ માટે બે ઘડિયાળ ટ્રૅક કરે છે: <strong>પ્રતિસાદ</strong> (ટિકિટ બન્યા ત્યારથી પ્રથમ વિશ્લેષક ક્રિયા સુધીનો સમય) અને <strong>નિરાકરણ</strong> (ટિકિટ બન્યા ત્યારથી ટિકિટ બંધ થવા સુધીનો સમય). બંને ટાર્ગેટ પ્રાથમિકતા પ્રમાણે સેટ થાય છે &mdash; એટલે P1 માટે પ્રતિસાદ માટે 30 મિનિટ અને નિરાકરણ માટે 4 કલાક હોઈ શકે, જ્યારે P4 માટે 8 કામકાજના કલાક અને 5 કામકાજના દિવસ હોઈ શકે.',
            'p2' => 'FreeITSM ના SLA એન્જિનમાં ચાર ડિઝાઇન પસંદગીઓ છે જે સમજવા જેવી છે:',
            'choice_business' => '<strong>કામકાજના કલાકો, ઘડિયાળનો સમય નહીં.</strong> જો ઑફિસ 5pm વાગ્યે બંધ થતી હોય, તો 1-કલાકના પ્રતિસાદ ટાર્ગેટ સાથે 4:30pm વાગ્યે ઉઠાવેલી P2 ટિકિટ 5:30pm વાગ્યે ભંગ થતી નથી. ઘડિયાળ આગલા કામકાજના દિવસે 9am વાગ્યે ફરી શરૂ થાય છે. જ્યારે વિશ્લેષકો રાત્રે ઘરે જાય છે ત્યારે આ ઉદ્યોગ ધોરણ અને એકમાત્ર ન્યાયી મોડેલ છે.',
            'choice_pause' => '<strong>થોભાવી શકાય તેવું.</strong> જ્યારે ટિકિટ "Pause SLA" તરીકે ફ્લેગ કરેલ સ્થિતિમાં હોય (જેમ કે <em>પ્રતિસાદની રાહમાં</em> અથવા <em>હોલ્ડ પર</em>), ત્યારે ઘડિયાળ અટકી જાય છે. ટિકિટ ફરી કાર્યકારી સ્થિતિમાં જાય ત્યારે તે ફરી શરૂ થાય છે.',
            'choice_compute' => '<strong>વાંચતી વખતે ગણતરી, સંગ્રહિત નહીં.</strong> તમે જ્યારે પણ જુઓ ત્યારે એન્જિન ટિકિટના ઓડિટ લોગ પરથી SLA સ્થિતિની ફરી ગણતરી કરે છે. કોઈ સંગ્રહિત કાઉન્ટર નથી જે સિંકમાંથી ખસી શકે. જો તમે પછીથી કોઈ કામકાજ કેલેન્ડરના કલાકો બદલો, તો દરેક જૂની ટિકિટનું SLA આગલી વખત જોવાય ત્યારે નવા કલાકો સામે ફરી ગણાય છે.',
            'choice_cutoff' => '<strong>એન્ફોર્સમેન્ટ કટઓફ.</strong> એડમિન-નિયંત્રિત "Enforce SLAs from" તારીખનો અર્થ એ છે કે તમે SLA ચાલુ કરો ત્યારે તમારી સિસ્ટમની હાલની ટિકિટો અચાનક પાછલી અસરથી ભંગ થતી નથી. ફક્ત કટઓફ પર અથવા પછી બનેલી ટિકિટો જ ટ્રૅક થાય છે.',
            'tip' => 'જો તમે ITIL માટે નવા છો: પ્રતિસાદ સમય સ્વીકૃતિ વિશે છે (કોઈએ તેને હાથમાં લીધું); નિરાકરણ સમય પૂર્ણતા વિશે છે (વપરાશકર્તાની સમસ્યા ઉકેલાઈ ગઈ). બંને ઘડિયાળ સ્વતંત્ર રીતે ચાલે છે અને તેમના જુદા જુદા ટાર્ગેટ હોય છે.',
        ],
        'blocks' => [
            'heading' => 'ચાર બિલ્ડિંગ બ્લોક્સ',
            'sub' => 'આ ચાર બાબતો ગોઠવો એટલે SLA ટ્રેકિંગ કાર્યરત થઈ જાય છે. બાકીનું બધું વૈકલ્પિક શુદ્ધિકરણ છે.',
            'cal_heading' => '1. કામકાજ કેલેન્ડરો',
            'cal_intro' => 'કેલેન્ડર નક્કી કરે છે કે તમારો સર્વિસ ડેસ્ક ક્યારે ખુલ્લો હોય છે. દરેક કેલેન્ડરમાં હોય છે:',
            'cal_tz' => '<strong>ટાઈમઝોન</strong> &mdash; IANA ટાઈમઝોન ઓળખકર્તા (દા.ત. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). DST સંક્રમણો આપમેળે સંભાળાય છે.',
            'cal_hours' => '<strong>સાપ્તાહિક કામકાજના કલાકો</strong> &mdash; દરેક અઠવાડિયાના દિવસ માટે એક પંક્તિ, જેમાં Open ચેકબૉક્સ અને શરૂઆત / સમાપ્તિ સમય હોય છે. નવા કેલેન્ડર ડિફોલ્ટ રીતે સોમ-શુક્ર 09:00-17:00, શનિ/રવિ બંધ પર સેટ થાય છે. Open તરીકે ફ્લેગ ન કરેલી પંક્તિનો અર્થ છે કે તે દિવસે ડેસ્ક બંધ છે.',
            'cal_holidays' => '<strong>રજાઓ</strong> &mdash; તારીખ + વૈકલ્પિક નામ. રજાઓ સાપ્તાહિક પેટર્નને ઓવરરાઇડ કરે છે (જો તે સોમવારે આવે તો પણ ડેસ્ક બંધ રહે છે).',
            'cal_default' => '<strong>ડિફોલ્ટ ફ્લેગ</strong> &mdash; બરાબર એક કેલેન્ડર ડિફોલ્ટ હોય છે. તમે અલગ ઉલ્લેખ ન કરો ત્યાં સુધી નવી પ્રાથમિકતાઓ તેને ઇનહેરિટ કરે છે.',
            'cal_outro' => 'તમે જરૂર હોય એટલા કેલેન્ડર બનાવી શકો છો &mdash; દરેક ઑફિસ માટે એક, દરેક ટીમ માટે એક, વિસ્તૃત કલાકોવાળા VIP ગ્રાહકો માટે એક. તેઓ SLA ટાર્ગેટ અને ભંગ-તપાસ એન્જિન દ્વારા શેર થાય છે.',
            'prio_heading' => '2. SLA ટાર્ગેટ સાથેની પ્રાથમિકતાઓ',
            'prio_intro' => 'Priorities ટૅબ પર (અથવા SLA ટૅબ પરના SLA Targets ટેબલ દ્વારા), દરેક પ્રાથમિકતામાં આ હોઈ શકે છે:',
            'prio_response' => '<strong>પ્રતિસાદ ટાર્ગેટ (મિનિટ)</strong> &mdash; પ્રથમ વિશ્લેષક ક્રિયા સુધી કેટલો સમય.',
            'prio_resolution' => '<strong>નિરાકરણ ટાર્ગેટ (મિનિટ)</strong> &mdash; ટિકિટ બંધ થાય ત્યાં સુધી કેટલો સમય.',
            'prio_calendar' => '<strong>કેલેન્ડર</strong> &mdash; આ પ્રાથમિકતાની ઘડિયાળ કયા કામકાજ કેલેન્ડર સામે ચાલે છે. ડિફોલ્ટ કેલેન્ડર વાપરવા માટે ખાલી છોડો.',
            'prio_outro' => 'બંને ટાર્ગેટ ફીલ્ડ ખાલી છોડવાથી તે પ્રાથમિકતા માટે SLA ટ્રેકિંગ સંપૂર્ણપણે નિષ્ક્રિય થાય છે &mdash; "Informational" અથવા "Backlog" જેવી પ્રાથમિકતા માટે ઉપયોગી જ્યાં સમયનું દબાણ ન હોય.',
            'pause_heading' => '3. Pause-SLA સ્થિતિઓ',
            'pause_intro' => 'Statuses ટૅબ પર એક ખાસ "Pause SLA" કૉલમ છે. જે પણ સ્થિતિ ટિકિટ ટીમના નિયંત્રણ બહારની કોઈ બાબત પર અટકેલી હોવાનું દર્શાવે તેને ફ્લેગ કરો. સામાન્ય ઉમેદવારો છે:',
            'pause_awaiting' => '<strong>પ્રતિસાદની રાહમાં</strong> &mdash; ગ્રાહક પાસેથી માહિતી બાકી છે. લગભગ સાર્વત્રિક રીતે ન્યાયી થોભાવ તરીકે સ્વીકૃત.',
            'pause_vendor' => '<strong>હોલ્ડ પર (વિક્રેતા)</strong> &mdash; Microsoft / તૃતીય-પક્ષ સપોર્ટની રાહ.',
            'pause_change' => '<strong>હોલ્ડ પર (ચેન્જ વિન્ડો)</strong> &mdash; ભવિષ્યની જાળવણી વિન્ડો માટે શેડ્યુલ કરેલ.',
            'pause_parts' => '<strong>હોલ્ડ પર (પાર્ટ્સ)</strong> &mdash; હાર્ડવેર ડિલિવરીની રાહ.',
            'pause_warn' => 'એક સામાન્ય "હોલ્ડ પર" સ્થિતિનો ઉપયોગ, ટિકિટ મુશ્કેલ હોય અથવા વિશ્લેષક વ્યસ્ત હોય ત્યારે, SLA ટાળવાના રસ્તા તરીકે થઈ શકે છે. જો તમારી ટીમમાં શિસ્ત હોય, તો આ ઠીક છે. જો ન હોય, તો ઉપરના વધુ ચોક્કસ પ્રકારોથી બદલવાનું વિચારો, અથવા <strong>Watchtower</strong> ડેશબોર્ડ પર આધાર રાખો જે 24 કલાકથી વધુ થોભાવેલી ટિકિટોને એમ્બર એલર્ટ તરીકે ફ્લેગ કરે છે.',
            'cutoff_heading' => '4. એન્ફોર્સમેન્ટ કટઓફ (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'સૌથી મહત્વની ગ્લોબલ સેટિંગ. જ્યાં સુધી તમે અહીં તારીખ-સમય સેટ ન કરો, ત્યાં સુધી SLA ટ્રેકિંગ સંપૂર્ણપણે નિષ્ક્રિય રહે છે &mdash; કોઈ ઘડિયાળ ચાલતી નથી, ઇનબોક્સ પર કોઈ પિલ દેખાતી નથી, કોઈ ભંગ ઈમેઇલ મોકલાતા નથી. તેને ભૂતકાળની તારીખ-સમય પર સેટ કરવાથી SLA તે બિંદુથી પાછલી અસરથી ચાલુ થાય છે. તેને ભવિષ્યની તારીખ-સમય પર સેટ કરવાથી ચાલુ થવાનું શેડ્યુલ થાય છે.',
            'cutoff_p2' => 'મોટાભાગની ટીમો SLA પહેલી વાર સક્ષમ કરે ત્યારે આને "now" પર સેટ કરે છે &mdash; હાલની ટિકિટો તેમની SLA-પહેલાંની સ્થિતિ જાળવી રાખે છે, તે ક્ષણથી પછીની નવી ટિકિટો ટ્રૅક થાય છે.',
        ],
        'behaviour' => [
            'heading' => 'વર્તન સેટિંગ્સ',
            'sub' => 'આ નિયંત્રિત કરે છે કે એન્જિન એજ કેસમાં કેવી પ્રતિક્રિયા આપે છે. ડિફોલ્ટ યોગ્ય છે &mdash; તમારે તેમને ફરીથી જોવાની જરૂર ફક્ત ત્યારે જ છે જો તમારી કોઈ ચોક્કસ પસંદગી હોય.',
            'prio_heading' => 'જ્યારે વચ્ચે પ્રાથમિકતા બદલાય',
            'prio_intro' => 'જો P3 ટિકિટ અડધા રસ્તે P1 પર અપગ્રેડ થાય (કારણ કે સમસ્યા વિચાર્યા કરતાં મોટી નીકળે), તો ત્રણ વાજબી વર્તન છે:',
            'prio_forward' => '<strong>Forward (ડિફોલ્ટ)</strong> &mdash; સંચિત કામકાજ મિનિટો જાળવી રાખો અને ફક્ત નવો ટાર્ગેટ લાગુ કરો. જો ટિકિટે તેના 8h P3 ટાર્ગેટમાંથી 2h વાપર્યા હોય, તો હવે તેના 1h P1 ટાર્ગેટ સામે 2h વપરાયેલ ગણાય છે &mdash; એટલે કે તે પહેલેથી જ ભંગ થયેલ છે. કદાચ સાચું: સમસ્યા આખો સમય P1 જ હતી, ટીમને ફક્ત ખ્યાલ નહોતો.',
            'prio_recompute' => '<strong>Recompute</strong> &mdash; ઘડિયાળ રીસેટ કરો અને ટિકિટ બન્યા ત્યારથી નવો ટાર્ગેટ પાછલી અસરથી લાગુ કરો. એક ચોખ્ખી પુનઃગણતરી.',
            'prio_reset' => '<strong>Reset</strong> &mdash; પ્રાથમિકતા બદલાવાની ક્ષણથી નવી ઘડિયાળ તાજી શરૂ કરો. ટીમ માટે સૌથી ઉદાર, પણ જો ઊંચી-પ્રાથમિકતાવાળી ટિકિટને અચાનક તાજી લાંબી ઘડિયાળ મળે તો ગ્રાહકોને છેતરાયાનું લાગી શકે.',
            'reopen_heading' => 'જ્યારે બંધ ટિકિટ ફરી ખોલાય',
            'reopen_intro' => 'જો ટિકિટ ફરી ખોલાય (વપરાશકર્તા બંધ થયા પછી જવાબ આપે):',
            'reopen_reset' => '<strong>Reset (ડિફોલ્ટ)</strong> &mdash; ફરી ખોલવાની ક્ષણથી તાજી પ્રતિસાદ અને નિરાકરણ ઘડિયાળ શરૂ કરો. ફરી ખોલવાને અસરકારક રીતે નવી ટિકિટ તરીકે ગણો.',
            'reopen_continue' => '<strong>Continue</strong> &mdash; બંધ થયા ત્યારના પસાર થયેલા સમયથી ફરી શરૂ કરો. મૂળ SLA ટાર્ગેટ લાગુ રહે છે.',
            'first_heading' => 'પ્રથમ-પ્રતિસાદની વ્યાખ્યા',
            'first_intro' => '"પ્રથમ પ્રતિસાદ" તરીકે શું ગણાય &mdash; એ ક્ષણ જે પ્રતિસાદ ઘડિયાળને અટકાવે છે?',
            'first_either' => '<strong>Either (ડિફોલ્ટ)</strong> &mdash; કોઈપણ પ્રકારની પ્રથમ વિશ્લેષક ક્રિયા: આઉટબાઉન્ડ ઈમેઇલ, સ્થિતિમાં ફેરફાર, સોંપણી.',
            'first_status' => '<strong>Status change</strong> &mdash; ફક્ત ડિફોલ્ટથી દૂરની સ્થિતિમાં ફેરફાર જ ગણાય છે. વધુ કડક &mdash; વિશ્લેષકે ટિકિટ પર ખરેખર કામ કર્યું હોવું જોઈએ, ફક્ત ક્લિક કર્યું નહીં.',
            'first_email' => '<strong>Outbound email</strong> &mdash; ફક્ત વિનંતી કરનારને ઈમેઇલ જવાબ જ ગણાય છે. સૌથી કડક &mdash; ગ્રાહકને અમારા તરફથી જવાબ મળવો જ જોઈએ.',
            'warn_heading' => 'ચેતવણી થ્રેશોલ્ડ ટકા',
            'warn_body' => 'ઇન્ડિકેટર લીલામાંથી એમ્બરમાં ફેરવાય તે પહેલાં SLA ટાર્ગેટમાંથી કેટલું પસાર થયું હોવું જોઈએ. ડિફોલ્ટ 80% છે &mdash; એટલે 60-મિનિટનો પ્રતિસાદ ટાર્ગેટ 48 મિનિટ પસાર થયા પછી એમ્બર બતાવે છે. આ ચેતવણી-ટ્રિગર ભંગ સૂચનાઓ પણ ચલાવે છે.',
        ],
        'breach' => [
            'heading' => 'ભંગ સૂચનાઓ',
            'sub' => 'વિભાગ પ્રમાણે ગોઠવી શકાય તેવા ઈમેઇલ નિયમો જે SLA ભંગની નજીક (ચેતવણી) અથવા ખરેખર ભંગ થાય ત્યારે ચાલે છે.',
            'intro' => 'દરેક નિયમને ચાર પરિમાણો હોય છે, બધા સ્વતંત્ર:',
            'scope_heading' => '1. સ્કોપ',
            'scope_body' => 'કાં તો <strong>Default</strong> (નિયમ દરેક વિભાગની ટિકિટોને લાગુ પડે છે) અથવા <strong>ચોક્કસ વિભાગ</strong>. નિર્ણય: તે વિભાગની ટિકિટો માટે વિભાગ-ચોક્કસ નિયમ ડિફોલ્ટ કરતાં જીતે છે. ડિફોલ્ટ નિયમ વગર, જે વિભાગોમાં ચોક્કસ નિયમ ન હોય તેમને કોઈ સૂચનાઓ મળતી નથી.',
            'trigger_heading' => '2. ટ્રિગર',
            'trigger_body' => 'કાં તો <strong>Warning</strong> (ટિકિટે ચેતવણી થ્રેશોલ્ડ પાર કરી છે &mdash; સંભવિત ભંગ) અથવા <strong>Breach</strong> (ટિકિટે તેનો ટાર્ગેટ ઓળંગ્યો છે &mdash; ખરેખર ભંગ). દરેક પોતાનો અલગ નિયમ છે, જેથી તમે દરેક માટે અલગ લોકોને સૂચિત કરી શકો.',
            'target_heading' => '3. ટાર્ગેટ',
            'target_body' => 'કઈ ઘડિયાળ જોવી &mdash; <strong>Response</strong>, <strong>Resolution</strong>, અથવા <strong>Both</strong>.',
            'recip_heading' => '4. પ્રાપ્તકર્તાઓ',
            'recip_intro' => 'આમાંથી કોઈપણ સંયોજન:',
            'recip_assignee' => '<strong>ટિકિટનો સોંપાયેલ</strong> &mdash; ટિકિટ હાલમાં જે વિશ્લેષક પાસે છે તે. જો સોંપાયેલ ન હોય તો છોડી દેવાય છે.',
            'recip_teams' => '<strong>ટિકિટના વિભાગની ટીમોના સભ્યો</strong> &mdash; ટિકિટના વિભાગ સાથે જોડાયેલી કોઈપણ ટીમનો દરેક વિશ્લેષક. ડિસ્ટ્રિબ્યુશન લિસ્ટ જાળવ્યા વિના આખી ક્યૂ આવરી લે છે.',
            'recip_specific' => '<strong>ચોક્કસ વિશ્લેષક</strong> &mdash; "SLA champion" / "service manager" પેટર્ન જ્યાં તે નામવાળી વ્યક્તિ છે, ભૂમિકા નહીં.',
            'recip_custom' => '<strong>કસ્ટમ ઈમેઇલ સરનામાં</strong> &mdash; અલ્પવિરામથી અલગ કરેલ ફ્રી-ટેક્સ્ટ. શેર કરેલા ઇનબોક્સ (<code>sla-alerts@company.com</code>), Slack/Teams ઈમેઇલ બ્રિજ, અથવા ડિસ્ટ્રિબ્યુશન લિસ્ટ માટે ઉપયોગી.',
            'tip' => 'દરેક ટિકિટ (ટાર્ગેટ, ટ્રિગર) દીઠ વધુમાં વધુ એક ઈમેઇલ મોકલે છે &mdash; ક્રોન વર્કર <code>sla_notifications_sent</code> ટેબલમાં શું મોકલાયું છે તે ટ્રૅક કરે છે. તેથી ચેતવણી એકવાર ચાલે છે, ભંગ એકવાર ચાલે છે, અને બસ &mdash; કોઈ સ્પામ લૂપ નહીં.',
            'warn' => '<strong>કોઈ નિયમ નહીં = કોઈ ઈમેઇલ નહીં.</strong> સિસ્ટમની દરેક ટિકિટ ભંગ થાય તો પણ, તમે ઓછામાં ઓછો એક નિયમ ઉમેરો ત્યાં સુધી કંઈ ચાલતું નથી. બધું આવરી લેવા માટે Default-scope Warning + Breach જોડીથી શરૂ કરો.',
        ],
        'cron' => [
            'heading' => 'ક્રોન જોબ સેટ કરવી',
            'sub' => 'ભંગ-તપાસ સ્ક્રિપ્ટ શેડ્યુલ પર ચાલવી જરૂરી છે. દર 5 મિનિટે એકવાર શ્રેષ્ઠ છે.',
            'p1' => 'UI માં દેખાતા SLA ઇન્ડિકેટર (ઇનબોક્સ પરની પિલ, રીડિંગ પેનમાંના પેનલ) પેજ લોડ થાય ત્યારે તરત ગણાય છે. પણ ભંગ ઈમેઇલ ફક્ત ત્યારે જ ચાલી શકે જ્યારે <em>કંઈક</em> સક્રિય રીતે ટિકિટો તપાસે, ભલે કોઈ તેમને જોતું ન હોય. તે કંઈક એટલે શેડ્યુલ્ડ ટાસ્ક &mdash; Windows પર, Task Scheduler; Linux પર, cron.',
            'p2' => 'સ્ક્રિપ્ટ FreeITSM ઇન્સ્ટોલ ડિરેક્ટરીમાં <code>cron/sla_breach_check.php</code> છે. તેને બે રીતે ચલાવી શકાય છે:',
            'cli_heading' => 'A. CLI (તમે નિયંત્રિત કરો છો તે સર્વર પર ભલામણ કરેલ)',
            'cli_note' => 'કોઈ પ્રમાણીકરણ જરૂરી નથી &mdash; ફાઇલસિસ્ટમ પરવાનગીઓ પહેલેથી જ નિયંત્રિત કરે છે કે કોણ તેને ચલાવી શકે.',
            'http_heading' => 'B. HTTP (શેર કરેલ હોસ્ટિંગ અથવા રિમોટ શેડ્યુલર માટે)',
            'http_note' => 'ટોકન પ્રથમ ઇન્સ્ટોલ પર આપમેળે જનરેટ થાય છે અને <code>system_settings</code> માં <code>sla_cron_token</code> કી હેઠળ સંગ્રહાય છે (32 હેક્સ કેરેક્ટર, ~128 બિટ્સ એન્ટ્રોપી). તે એન્ક્રિપ્ટેડ સંગ્રહાય છે, તેથી પંક્તિ સીધી વાંચવાથી ટોકનને બદલે <code>ENC:…</code> મળે છે. તમારું આ રીતે શોધો:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Task Scheduler ખોલો (<code>taskschd.msc</code>) અને આ સેટિંગ્સ સાથે નવું ટાસ્ક બનાવો:',
            'tbl_field' => 'ફીલ્ડ',
            'tbl_value' => 'મૂલ્ય',
