            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Start in',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'તમારા crontab માં એક લાઇન ઉમેરો (<code>crontab -e</code>):',
            'sec_heading' => 'સુરક્ષા &mdash; HTTP એન્ડપોઈન્ટને શું સુરક્ષિત કરે છે',
            'sec_intro' => 'ત્રણ સ્તરો, બધા આપમેળે લાગુ થાય છે:',
            'sec_token' => '<strong>1. શેર કરેલ-ગુપ્ત ટોકન</strong> &mdash; દરેક ઇન્સ્ટોલ માટે 128-બિટ રેન્ડમ, ટાઈમિંગ એટેક અટકાવવા માટે કોન્સ્ટન્ટ-ટાઈમ મેચિંગ સાથે સરખાવાય છે.',
            'sec_lockout' => '<strong>2. IP દીઠ નિષ્ફળ-પ્રમાણીકરણ લોકઆઉટ</strong> &mdash; છેલ્લા એક કલાકમાં એક જ IP પરથી 10 થી વધુ ખોટા-ટોકન પ્રયાસો 1-કલાકનું 429 લોકઆઉટ ટ્રિગર કરે છે. fail2ban ની જરૂર વગર બ્રુટ-ફોર્સ પ્રોબિંગને હરાવે છે.',
            'sec_interval' => '<strong>3. સફળ રનો વચ્ચે ન્યૂનતમ અંતરાલ</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (ડિફોલ્ટ 30s). છેલ્લા સફળ રન પછી આનાથી વહેલા આવતી માન્ય-ટોકન વિનંતીને પણ 429 મળે છે. આકસ્મિક ડબલ-શેડ્યુલિંગ અને રનઅવે લૂપને હરાવે છે.',
            'log_heading' => 'એક્ટિવિટી લોગ',
            'log_body' => 'દરેક કૉલ (સ્વીકૃત અથવા નકારેલ) <code>sla_cron_runs</code> ટેબલમાં ટાઈમિંગ, પરિણામ, ગણતરી અને ક્લાયન્ટ IP સાથે લોગ થાય છે. SLA સેટિંગ્સ ટૅબના તળિયે <strong>Cron Activity</strong> પેનલમાં છેલ્લા 20 રન જુઓ &mdash; શેડ્યુલ ચાલી રહ્યું છે તે ચકાસવા અને કોઈપણ નિષ્ફળ-પ્રમાણીકરણ પ્રયાસોનું ઓડિટ કરવા માટે ઉપયોગી. <code>sla_cron_log_retention_days</code> (ડિફોલ્ટ 30) પછી પંક્તિઓ આપમેળે કાઢી નખાય છે જેથી ટેબલ નાનું રહે.',
        ],
        'examples' => [
            'heading' => 'ઉદાહરણો',
            'sub' => 'સાદા સિંગલ-ટાઈમઝોન કેસથી લઈને વધુ મુશ્કેલ ક્રોસ-ટાઈમઝોન કેસ સુધી જ્યાં "ન્યાયી" ને વ્યાખ્યાયિત કરવાની જરૂર પડે છે.',
            'ex1_heading' => 'ઉદાહરણ 1: UK માં ઉઠાવેલી ટિકિટ, UK માં સર્વિસ ડેસ્ક',
            'ex1_title' => 'સાદો કેસ',
            'ex1_tag' => 'સિંગલ ટાઈમઝોન',
            'ex1_setup' => '<strong>સેટઅપ:</strong> ટાઈમઝોન <code>Europe/London</code> સાથે <em>UK Office</em> નામનું એક કામકાજ કેલેન્ડર, સોમ-શુક્ર 09:00-17:00, કોઈ રજા નહીં. P2 પ્રાથમિકતાનો 1-કલાકનો પ્રતિસાદ ટાર્ગેટ અને 4-કલાકનો નિરાકરણ ટાર્ગેટ છે, બંને <em>UK Office</em> કેલેન્ડર સામે ચાલે છે.',
            'ex1_scenario' => '<strong>સ્થિતિ:</strong> વપરાશકર્તા <strong>બુધવારે 16:30 UK</strong> વાગ્યે P2 ટિકિટ ઉઠાવે છે.',
            'ex1_timeline' => 'બુધ 16:30 UK &mdash; <strong>ટિકિટ બની</strong>, પ્રતિસાદ ઘડિયાળ શરૂ.
બુધ 17:00 UK &mdash; ઑફિસ બંધ થાય છે, ઘડિયાળ થોભે છે (60 મિનિટના ટાર્ગેટમાંથી 30 મિનિટ વપરાયેલ).
ગુરુ 09:00 UK &mdash; ઑફિસ ખુલે છે, ઘડિયાળ ફરી શરૂ.
ગુરુ 09:30 UK &mdash; વિશ્લેષક જવાબ આપે છે. પ્રતિસાદ SLA છેલ્લી ઘડીએ પૂરું થયું (60 મિનિટ વપરાયેલ, 60 મિનિટ ટાર્ગેટ).',
            'ex1_outro' => 'જો વિશ્લેષકે <strong>ગુરુવાર 10:00 UK</strong> સુધી જવાબ ન આપ્યો હોત, તો પ્રતિસાદ <strong>30 મિનિટથી ભંગ</strong> થયો હોત (60 મિનિટના ટાર્ગેટ સામે 90 મિનિટ વપરાયેલ &mdash; બુધવાર સાંજથી 30, ગુરુવાર સવારથી 60). 1-કલાકની ઘડિયાળ ફક્ત કામકાજના કલાકોમાં જ ટિક કરે છે, પણ દિવસના અંતની ટિકિટ ઑફિસ ફરી ખુલે ત્યારે રાતોરાત તેના મોટાભાગના બજેટને ખાઈ જાય છે &mdash; 09:00 વાગ્યે આવતા વિશ્લેષક માટે એવું માની લેવું સહેલું છે કે તેમની પાસે આખો કલાક છે, જ્યારે વાસ્તવમાં ફક્ત 30 મિનિટ જ બાકી છે.',
            'ex2_heading' => 'ઉદાહરણ 2: UK માં ઉઠાવેલી ટિકિટ, એસ્ટોનિયામાં સર્વિસ ડેસ્ક',
            'ex2_title' => 'ક્રોસ-ટાઈમઝોન કેસ',
            'ex2_tag' => '"ન્યાયી" ને વ્યાખ્યાયિત કરવાની 3 રીતો',
            'ex2_setup' => '<strong>સેટઅપ:</strong> UK ગ્રાહકો (<code>Europe/London</code>, GMT/BST), એસ્ટોનિયા સર્વિસ ડેસ્ક (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>UK કરતાં 2 કલાક આગળ</strong>). બંને ડેસ્ક નામમાત્ર સ્થાનિક સમય પ્રમાણે 09:00-17:00 કામ કરે છે.',
            'ex2_scenario' => '<strong>સ્થિતિ:</strong> UK ગ્રાહક <strong>શુક્રવારે 16:30 UK</strong> વાગ્યે P2 ટિકિટ ઉઠાવે છે (= 18:30 એસ્ટોનિયા, એસ્ટોનિયા બંધ થયા પછી). એસ્ટોનિયાના વિશ્લેષક માટે તેના પર કામ કરવાની આગલી તક સોમવારે 09:00 એસ્ટોનિયા (= 07:00 UK) છે. પ્રતિસાદ ટાર્ગેટ 1 કલાક છે.',
            'ex2_question' => 'SLA એ શું કહેવું જોઈએ? ત્રણ સમર્થનીય જવાબો છે, દરેક અલગ અર્થમાં ન્યાયી. તમારો સર્વિસ કોન્ટ્રાક્ટ શું વચન આપે છે તેના આધારે તમે પ્રાથમિકતાને કયું કેલેન્ડર સોંપવું તે પસંદ કરો છો.',
            'optA_label' => 'વિકલ્પ A &mdash; ગ્રાહક-કેન્દ્રિત',
            'optA_p1' => '<strong><em>UK</em> કલાકોવાળું કેલેન્ડર વાપરવા માટે પ્રાથમિકતા સેટ કરો.</strong> વિશ્લેષક ક્યાં છે તેને ધ્યાનમાં લીધા વગર, ઘડિયાળ UK 09:00-17:00 સામે ટિક કરે છે.',
            'optA_p2' => 'ઉપરની સ્થિતિમાં, ટિકિટ શુક્રવારે 16:30 UK વાગ્યે ઉઠાવાય છે: ઘડિયાળ 16:30&ndash;17:00 UK શુક્રવાર ચાલે છે (30 મિનિટ વપરાયેલ), રાત + સપ્તાહાંત દરમિયાન થોભે છે, સોમવારે 09:00 UK વાગ્યે ફરી શરૂ થાય છે. જો એસ્ટોનિયાનો વિશ્લેષક સોમવારે 10:00 એસ્ટોનિયા (= 08:00 UK) વાગ્યે જવાબ આપે, તો UK કેલેન્ડર હજુ થોભેલું છે (UK ઑફિસ 09:00 UK વાગ્યે ખુલે છે), તેથી કોઈ વધારાની મિનિટ ટિક કરતી નથી &mdash; વપરાશ 30 મિનિટ પર જ રહે છે. <strong>SLA 30 મિનિટના માર્જિનથી પૂરું થયું</strong>. 09:30 UK (= 11:30 એસ્ટોનિયા) પછીનો કોઈપણ જવાબ ભંગ થશે.',
            'optA_p3' => '<em>ન્યાયી કોના માટે:</em> ગ્રાહક માટે. તેમનો અનુભવ તેમના કામકાજના દિવસ સાથે મેળ ખાય છે.<br><em>ટ્રેડ-ઓફ:</em> એસ્ટોનિયાના વિશ્લેષકો પાસેથી 09:00-17:00 UK સમય (= 11:00-19:00 એસ્ટોનિયા) ઉપલબ્ધ રહેવાની અપેક્ષા રખાય છે, જે તેમના કામકાજના દિવસને 2 કલાક લંબાવે છે.',
            'optB_label' => 'વિકલ્પ B &mdash; વિશ્લેષક-કેન્દ્રિત',
            'optB_p1' => '<strong><em>એસ્ટોનિયા</em> કલાકોવાળું કેલેન્ડર વાપરવા માટે પ્રાથમિકતા સેટ કરો.</strong> ઘડિયાળ એસ્ટોનિયા 09:00-17:00 સામે ટિક કરે છે.',
            'optB_p2' => 'એ જ સ્થિતિ: ટિકિટ શુક્રવારે 18:30 એસ્ટોનિયા (બંધ થયા પછી) ઉઠાવાય છે, ઘડિયાળ આખા સપ્તાહાંત થોભેલી રહે છે, સોમવારે 09:00 એસ્ટોનિયા (= 07:00 UK) વાગ્યે ટિક કરવાનું શરૂ કરે છે. જો વિશ્લેષક સોમવારે 09:30 એસ્ટોનિયા (= 07:30 UK) વાગ્યે જવાબ આપે, તો પ્રતિસાદ SLA એ 60 મિનિટના ટાર્ગેટમાંથી 30 મિનિટ વાપર્યા છે &mdash; <strong>30 મિનિટના માર્જિનથી પૂરું</strong>. UK ગ્રાહકે શુક્રવારે 16:30 UK વાગ્યે ટિકિટ ઉઠાવી અને સોમવારે 07:30 UK વાગ્યે જવાબ મળ્યો &mdash; તેમની ઘડિયાળના સમય પ્રમાણેની રાહ SLA સૂચવે છે તેના કરતાં ઘણી લાંબી હતી.',
            'optB_p3' => '<em>ન્યાયી કોના માટે:</em> વિશ્લેષકો માટે. તેઓ સામાન્ય કલાકોમાં કામ કરે છે.<br><em>ટ્રેડ-ઓફ:</em> જો શુક્રવાર-બપોરની ટિકિટ સોમવાર સવારના એસ્ટોનિયા સમય સુધી સ્વીકારાય નહીં પણ રિપોર્ટ કહે કે પ્રતિસાદ SLA 1 કલાક હતું, તો UK માં ગ્રાહકોને એવું લાગી શકે કે SLA "જૂઠું બોલે છે". ખાતરી કરો કે તમારો સર્વિસ કોન્ટ્રાક્ટ સ્પષ્ટ કરે છે કે SLA સપોર્ટ-ડેસ્કના કલાકો સામે ચાલે છે.',
            'optC_label' => 'વિકલ્પ C &mdash; ઓવરલેપ વિન્ડો (સૌથી કડક)',
            'optC_p1' => '<strong>ફક્ત બંને ડેસ્ક ખુલ્લા હોય તેવા કલાકોને આવરી લેતું કેલેન્ડર વાપરવા માટે પ્રાથમિકતા સેટ કરો.</strong> UK 09:00-17:00 એસ્ટોનિયા 09:00-17:00 (= UK 07:00-15:00) સાથે <strong>UK 09:00-15:00 વિન્ડો</strong> દરમિયાન ઓવરલેપ થાય છે &mdash; દરેક કામકાજના દિવસે 6 કલાક.',
            'optC_p2' => 'એ જ સ્થિતિ: ટિકિટ શુક્રવારે 16:30 UK વાગ્યે ઉઠાવાય છે (ઓવરલેપની બહાર, કારણ કે ઓવરલેપ 15:00 UK વાગ્યે બંધ થાય છે), ઘડિયાળ સપ્તાહાંત દરમિયાન થોભેલી રહે છે, સોમવારે 09:00 UK (= 11:00 એસ્ટોનિયા, ઓવરલેપ ફરી ખુલવાની ક્ષણ) વાગ્યે ફરી શરૂ થાય છે. જો એસ્ટોનિયાનો વિશ્લેષક 11:30 એસ્ટોનિયા (= 09:30 UK) વાગ્યે જવાબ આપે, તો પ્રતિસાદ SLA એ 60 મિનિટના ટાર્ગેટમાંથી 30 મિનિટ વાપર્યા છે &mdash; <strong>30 મિનિટના માર્જિનથી પૂરું</strong>. જવાબ ઓવરલેપ વિન્ડો દરમિયાન થયો તેથી તે તરત જ ગણાય છે.',
            'optC_p3' => '<em>ન્યાયી કોના માટે:</em> બંને પક્ષો માટે &mdash; SLA ફક્ત તે કલાકોમાં જ ટિક કરે છે જ્યારે ડેસ્ક ખરેખર ટિકિટ પર પ્રગતિ કરી શકે અને ગ્રાહક જવાબ મેળવવા માટે તેમના ડેસ્ક પર હોય.<br><em>ટ્રેડ-ઓફ:</em> ટૂંકી દૈનિક વિન્ડોનો અર્થ છે આક્રમક ટાર્ગેટ પૂરા કરવા માટે લાંબો ઘડિયાળ-સમય. 4-કલાકનો નિરાકરણ ટાર્ગેટ ઓવરલેપના 1.5 દિવસમાં ફેલાય છે, જ્યારે સામાન્ય 8-કલાકના કેલેન્ડર સાથે તે એક જ દિવસમાં પૂરું થાત.',
            'choose_tip' => '<strong>કેવી રીતે પસંદ કરવું:</strong> તમારો સર્વિસ કોન્ટ્રાક્ટ જુઓ. જો તેમાં "response within 1 hour of receipt" લખ્યું હોય &mdash; તે વિકલ્પ A છે (ગ્રાહકની ઘડિયાળ). જો તેમાં "response within 1 working hour" લખ્યું હોય &mdash; તે સામાન્ય રીતે વિકલ્પ B છે (જે પણ ડેસ્ક કામ કરી રહ્યું હોય). જો તેમાં "within 1 hour of mutual availability" લખ્યું હોય &mdash; તે વિકલ્પ C છે. જો કોઈ કોન્ટ્રાક્ટ ન હોય, તો ટીમને પૂછો: શું તમે એસ્ટોનિયાના કલાકોની બહાર દબાણ અનુભવવા માંગો છો (વિકલ્પ A), કે UK ગ્રાહકોને ક્યારેક અવગણાયેલા લાગે તે તમે ઇચ્છો છો (વિકલ્પ B)?',
            'ex3_heading' => 'ઉદાહરણ 3: વિક્રેતાની રાહ દરમિયાન ઘડિયાળ-થોભાવો',
            'ex3_title' => 'થોભાવ સ્થિતિઓ વ્યવહારમાં કેવી રીતે કામ કરે છે',
            'ex3_tag' => 'ઘડિયાળ-થોભાવો',
            'ex3_setup' => '<strong>સેટઅપ:</strong> 8 કામકાજ-કલાકના નિરાકરણ ટાર્ગેટવાળી P3 પ્રાથમિકતા, UK કેલેન્ડર, "Awaiting Vendor" સ્થિતિ <em>Pause SLA</em> તરીકે ફ્લેગ કરેલ.',
            'ex3_scenario' => '<strong>સ્થિતિ:</strong> ટિકિટ સોમવારે 09:00 UK વાગ્યે ઉઠાવાય છે. વિશ્લેષક સોમવારે 11:00 UK વાગ્યે Microsoft ને એસ્કેલેટ કરે છે અને ટિકિટને "Awaiting Vendor" પર ખસેડે છે. Microsoft બુધવારે 14:00 UK વાગ્યે જવાબ આપે છે. વિશ્લેષક ફિક્સ લાગુ કરે છે અને ગુરુવારે 10:00 UK વાગ્યે બંધ કરે છે.',
            'ex3_timeline' => 'સોમ 09:00 &mdash; ટિકિટ બની, નિરાકરણ ઘડિયાળ ચાલુ.
સોમ 11:00 &mdash; "Awaiting Vendor" પર ખસેડાઈ, <strong>ઘડિયાળ થોભી</strong> (2h વપરાયેલ).
બુધ 14:00 &mdash; "In Progress" પર પાછી ખસેડાઈ, <strong>ઘડિયાળ ફરી શરૂ</strong>.
બુધ 17:00 &mdash; ઑફિસ બંધ (કુલ 5h વપરાયેલ).
ગુરુ 09:00 &mdash; ઑફિસ ખુલે છે.
ગુરુ 10:00 &mdash; ટિકિટ બંધ (કુલ 6h વપરાયેલ). 8h ટાર્ગેટ સામે <strong>SLA પૂરું</strong>.',
            'ex3_outro' => 'ઘડિયાળ-સમય પસાર થયો: ~3 દિવસ. SLA પસાર થયો: 6 કામકાજના કલાક. થોભાવ-સ્થિતિ ફ્લેગ વગર, SLA એ વિક્રેતાની રાહના બધા 2 દિવસ + કામકાજના કલાકો ગણ્યા હોત, કુલ ~18 કામકાજના કલાક &mdash; ભંગથી ઘણું વધારે.',
        ],
        'trouble' => [
            'heading' => 'મુશ્કેલીનિવારણ',
            'sub' => 'સામાન્ય સમસ્યાઓ અને શું તપાસવું.',
